// Typed Gateway client. The TYPES come from the OpenAPI document the Gateway emits
// (src/api/schema.ts, generated by `npm run gen:api`), so the C# DTOs stay the single source
// of truth: a C# DTO change that is not reflected in a regenerated schema fails this build.
//
// The credential on every call is the PER-DEVICE KEY this browser obtained at enrollment
// (issue #908 for the phone, issue #1088 for the desktop Cockpit) - the one standing credential in
// the system. No token is injected into the page; the shell carries no secret until the person
// signs in on devthrottle.com and the device enrolls with the Gateway.
import type { components } from "./schema";
import type { SpokenSpan } from "../dictation/composerProvenance";
import type { SessionHistoryDto } from "../history/types";
import { planUploadChunks } from "./chunking";
import { getDeviceKey } from "../auth/deviceKey";
import { listAccounts, removeAccount } from "../auth/accountStore";
import { publishDictationStatus } from "../dictation/status";
import { reportGatewayReachable, reportGatewayUnreachable } from "../connection/health";

export type SessionDto = components["schemas"]["SessionDto"] & {
  /** Epic #1159 step A: whether the machine owning this session is reachable right now - its tunnel is up.
   *  Stamped by the Gateway's roster read and rendered verbatim; the client never re-derives it. It is the
   *  Gateway's answer to "may this session nag the human", which stopped being the same question as "should
   *  this session be shown" the moment the roster began serving machines nobody can reach. Optional because
   *  an older Gateway does not stamp it and a Director-local response leaves it null - see
   *  machineCanBeActedOn, which treats only an explicit false as unreachable. */
  machineReachable?: boolean | null;
  /** The model this session's agent is running right now, exactly as the agent's own records spell it
   *  (`claude-fable-5`, `gpt-5.6-sol`). Re-read at every turn-end by the owning Director, so a mid-session
   *  model switch is reflected. Null when no turn has finished yet or when the agent cannot report a model
   *  at all - which of those two it is comes from `modelDisplay`, never from guessing here. */
  currentModel?: string | null;
  /** The Gateway's folded model verdict (see the C# ModelDisplay): the badge text, the full id, and WHICH
   *  of the two absences applies when there is no model. Rendered verbatim - a client never works out for
   *  itself whether a missing model means "not yet" or "never". Null from an older Gateway and in
   *  Director-local responses. */
  modelDisplay?: ModelDisplay | null;
};

/** The Gateway-computed model display verdict (see the C# ModelDisplay), rendered verbatim by the Fleet
 *  Map, the roster and the session view. Hand-written here for the same reason as `machineReachable`
 *  above: the committed `schema.ts` predates the field. Delete it when the schema is next regenerated
 *  properly - the two declarations agree, so it is harmless until then. */
export interface ModelDisplay {
  /** `reported` | `notRecordedYet` | `notReported`. A style key, never a decision to re-make. */
  kind?: string;
  /** The badge text, verbatim: the shortened model id, or the words for whichever absence this is. */
  text?: string;
  /** The full recorded id, for lane headers and tables; null in both absent states. */
  modelId?: string | null;
  /** The tooltip, verbatim: the full id, or the sentence saying which absence this is. */
  tooltip?: string;
  /** True in both absent states, so a card can mute the chip without branching on `kind`. */
  isAbsent?: boolean;
}

// WHY THIS FIELD IS DECLARED HERE AND NOT IN THE GENERATED SCHEMA. `schema.ts` is produced by
// openapi-typescript from a live Gateway's OpenAPI document, and regenerating it today does not produce a
// clean addition: the committed copy is weeks behind, and a fresh dump taken from a test-booted Gateway
// omits about twenty routes that are still very much mapped - /shutdown and the whole /ingest/recording
// family among them, the latter used by this package's own recorder upload. Those routes are registered
// conditionally, so a Gateway booted without their dependencies never advertises them, and taking that dump
// as truth would silently delete live routes from the typed client contract.
//
// So the regeneration is left for someone who can boot a fully-wired Gateway and verify the diff, and this
// one additive field rides in the hand-written layer instead. When the schema is next regenerated properly
// it will carry `machineReachable` itself and this intersection becomes redundant - harmlessly so, since the
// two declarations agree. Delete it then, not before.
/** The Gateway-computed voice display verdict (see the C# VoiceDisplay). Rendered verbatim by the Voice
 *  screen; the client never re-derives it - all voice-screen ruling lives on the Gateway. */
export type VoiceDisplay = components["schemas"]["VoiceDisplay"];

// Request bodies are typed from the generated OpenAPI schema (the C# DTOs stay the source of
// truth). The buffer/escape/interrupt/transcription responses are not declared in the schema (the
// Gateway returns them via Results.Json without a [Produces] annotation), so they are read with
// narrow local shapes for exactly the fields the mobile views consume.
type PromptRequest = components["schemas"]["PromptRequest"];
type NewSessionRequest = components["schemas"]["NewSessionRequest"];

// One machine (Director) in the fleet, projected from GET /directors. The response is not declared
// in the OpenAPI schema (the Gateway returns it via Results.Json without a [Produces] annotation),
// so it is read with this narrow local shape - the exact subset the add-session flow consumes,
// mirroring the Android phone/CcDirectorClient DirectorInfo.
export interface DirectorInfo {
  directorId: string;
  machineName: string;
  /** The instance's user-editable display name (devthrottle_internal#1176). Empty when unnamed or from
   *  an older Director - pickers fall back to machineName. */
  displayName: string;
  /** Best-effort version label for the picker subtitle. */
  version: string;
  /** When the Director process started (ISO 8601 UTC), or empty. Drives the picker "up <uptime> /
   *  started <when>" subtitle (issue #848); empty/unparseable degrades to last-seen only. */
  startedAt: string;
  /** When the Gateway last heard from this Director (ISO 8601), or empty. Used to default-select. */
  lastSeen: string;
  /** The Director's Control API endpoint, e.g. "http://127.0.0.1:7880" or a tailnet URL. Carries the
   *  PORT, which is what distinguishes several Directors (slots) on the SAME machine in the picker. */
  controlEndpoint: string;
}

/**
 * GET /healthz - what the running Gateway reports about itself. Backs the mobile About screen.
 *
 * `directors` and `sessions` are OPTIONAL: the hosted Gateway omits them entirely, because /healthz is
 * public and carries no credential, so it has no tenant and a fleet-global count would span every
 * account. Render an absent count as "not reported" - never coerce it, or `String(undefined)` puts the
 * literal text "undefined" on the screen and a `?? 0` would claim the fleet is empty.
 */
export interface GatewayHealth {
  status: string;
  directors?: number;
  sessions?: number;
  version: string;
  serverTime: string;
}

// One recently-used repository on a Director, projected from GET /directors/{id}/repos. Also not in
// the OpenAPI schema; read with this narrow local shape, mirroring the Android RepoInfo.
export interface RepoInfo {
  name: string;
  path: string;
  /** When a session last used this repo (ISO 8601), or empty. The list is sorted newest-used first. */
  lastUsed: string;
}

// One selectable agent on a Director, projected from GET /directors/{id}/agents (issue #1497): the
// machine's configured, enabled agents, one per kind - the remote counterpart of the desktop New
// Session dialog's agent radios. Not in the OpenAPI schema; read with this narrow local shape.
export interface AgentChoice {
  /** The agent kind to launch, sent verbatim as the create request's `agent` (e.g. "ClaudeCode"). */
  type: string;
  /** The configured display name shown to the user. */
  displayName: string;
  /** The configured default model id, or empty when the agent uses its own built-in default. */
  defaultModel: string;
  /** A friendly label for the default model (e.g. "Opus 4.8"), or empty - shown so the user sees which
   *  model the agent will use. The desktop shape: pick the agent, the model comes from its default. */
  modelLabel: string;
}

// The app's credential is the per-device key it obtained at enrollment (issue #908/#1088), read from
// the device-key store - NOT a token injected into the page (the shell carries no secret). Empty until
// this device has enrolled, in which case the caller (the auth gate) routes to the Sign in screen.
function gatewayToken(): string {
  return getDeviceKey();
}

// Exported so the dictation transcription calls (which post raw audio bytes and read a transcript)
// attach the same Bearer the rest of the client uses. Empty headers before enrollment; the app gates
// on the device key so no data call runs without one.
export function authHeaders(): HeadersInit {
  const token = gatewayToken();
  return token ? { Authorization: `Bearer ${token}` } : {};
}

// Mirror the per-device key into the cc-gateway-token cookie (issue #817/#908). A browser WebSocket
// cannot set an Authorization header, so the live terminal stream (GET /sessions/{sid}/stream)
// authenticates via this cookie, which the same-origin handshake carries and the Gateway's
// AuthMiddleware accepts (HasValidToken checks the cookie against the shared token OR an active
// per-device key). The same constraint applies to any bare <img>/<iframe> src that hits a gated
// Gateway route - the Local Files viewer's image/PDF/HTML modes - because those elements also cannot
// carry a Bearer header; they authenticate through this cookie exactly as the stream does.
// The key is already in this origin's storage, so the cookie exposes nothing new; it is scoped to this
// origin. A no-op before enrollment (no key yet - the stream is never opened then).
//
// PERSISTENT (Max-Age one year), not a session cookie: an installed PWA (the phone) can evict a
// session cookie between launches, after which a bare <img>/<iframe> src loads with no credential and
// gets a 401 - the Local Files viewer's "Could not load image" failure. Because the credential already
// lives on disk in localStorage, persisting it in the cookie exposes nothing further; it just keeps the
// cookie-authenticated resource loads working after the app is closed and reopened.
export function ensureGatewayCookie(): void {
  const token = gatewayToken();
  if (!token) return;
  const oneYearSeconds = 60 * 60 * 24 * 365;
  document.cookie = `cc-gateway-token=${encodeURIComponent(token)}; path=/; SameSite=Lax; Max-Age=${oneYearSeconds}`;
}

// THE COOKIE IS HttpOnly, SO ONLY THE SERVER CAN MOVE IT (devthrottle_internal #1509).
//
// GatewayTokenCookie writes cc-gateway-token with HttpOnly set, which means a document.cookie write or
// delete from this side is silently IGNORED - no error, no effect, and nothing in a test would notice.
// The first version of the account switch and sign-out did exactly that and looked correct everywhere,
// while in a real browser the cookie stayed on the previous account: the WebSockets and the bare
// image/iframe loads that authenticate BY COOKIE, because they cannot carry a Bearer header, went on
// running as an account the person had left or signed out of - for the cookie's full 30-day life.
//
// So both are server calls now (POST/DELETE /account/device-cookie), and both are AWAITED before the
// hard navigation that follows them: a reload mid-flight would leave the cookie and the active account
// disagreeing, which is the precise state this exists to prevent.
//
// ensureGatewayCookie above is left as it was. It is the enrollment-time path, where the Gateway's own
// response has already set the cookie server-side, and its document.cookie write is a no-op wherever
// that is true.

/**
 * Move the cookie onto the ACTIVE account, server-side. Sent with the active Bearer; the Gateway mirrors
 * the credential it just authenticated, so this can only ever install a key this browser already holds.
 * Never throws - a switch must not be blocked by a transport failure, and the reload that follows
 * re-runs it.
 */
export async function adoptGatewayCookie(signal?: AbortSignal): Promise<void> {
  const token = gatewayToken();
  if (!token) return;
  try {
    await fetch("/account/device-cookie", { method: "POST", headers: { Authorization: `Bearer ${token}` }, signal });
  } catch {
    /* offline: the cookie follows on the next load, which calls this again */
  }
}

/**
 * Clear the cookie server-side. MUST be called while the key is STILL HELD - the request has to
 * authenticate to be accepted, so a caller that forgets the key locally first can never clear the
 * cookie afterwards. Never throws; a failure is reported by the caller rather than stranding the
 * sign-out half-done.
 */
export async function clearGatewayCookie(signal?: AbortSignal): Promise<boolean> {
  const token = gatewayToken();
  if (!token) return true;
  try {
    const res = await fetch("/account/device-cookie", {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
      signal,
    });
    return res.ok;
  } catch {
    return false;
  }
}

// The redirect target when a credentialed call is rejected (401) mid-session is SHELL-AWARE, because
// the two shells that share this client re-gate through sign-in entries at different paths: the
// mobile PWA's enrollment screen lives at /mobile/signin, the desktop Cockpit's at /signin. Shared
// client-core must NOT hardcode either shell's route for the other (issue #1024), so the target is
// INJECTED per shell at startup via configureUnauthorizedRedirect. The resolver is given the current
// in-app location so a shell that carries the route forward (the desktop next=) can build a
// round-trip target.
export interface SignInLocation {
  pathname: string;
  search: string;
}
export type SignInRedirect = (current: SignInLocation) => string;

// The desktop Cockpit's sign-in redirect (issue #1088): re-gate through the Cockpit's own /signin
// route - the SAME shared client-core enrollment flow the phone uses - carrying the current route in
// next= so the browser lands back where it was once this device is enrolled again. This replaced the
// former /login token-wall re-gate (the raw-token wall is break-glass only, issue #1077): after a
// website revoke the desktop returns to the shared sign-in flow, never to login.html.
export function cockpitSignInRedirect(current: SignInLocation): string {
  return `/signin?next=${encodeURIComponent(current.pathname + current.search)}`;
}

// The mobile PWA's sign-in redirect: its own /mobile/signin enrollment screen, absolute under the
// /mobile basename so it works from any in-app route. This is what the mobile shell installs at startup,
// and it is the default so an unconfigured client-core still serves the shell that historically owned it.
export function mobileSignInRedirect(): string {
  return "/mobile/signin";
}

let signInRedirect: SignInRedirect = mobileSignInRedirect;

// Each shell installs its own sign-in redirect at startup (the mobile PWA -> mobileSignInRedirect, the
// desktop Cockpit -> cockpitSignInRedirect), so a mid-session 401 re-gates through the entry that shell
// actually uses instead of the mobile route baked into shared client-core (issue #1024).
export function configureUnauthorizedRedirect(redirect: SignInRedirect): void {
  signInRedirect = redirect;
}

// The configured sign-in target for the given current location. Exported so onUnauthorized has one
// place to resolve it and the shell-aware behavior is unit-testable without a DOM.
export function resolveSignInTarget(current: SignInLocation): string {
  return signInRedirect(current);
}

// Called when the Gateway answers 401 to a credentialed call: the device key was revoked (from the
// website's "Your devices") or is otherwise no longer valid. Forget it and send the user back to the
// shell's own Sign in entry, so a revoke on the account promptly ends access (the revoke round-trip,
// issue #908). A hard navigation (not the router) guarantees the whole app re-gates from a clean state.
// @param rejectedKey The credential the failed request was SENT with. Required, because "whichever
//   account is active when the response lands" is a different thing: a roster poll made as A can return
//   401 after the person has switched to B, and deleting the active account would then remove B - a
//   perfectly good login - while leaving the actually-revoked A in place. The next poll would then take
//   out A too, so one revoked key could sign the browser out of two valid accounts
//   (devthrottle_internal #1509).
function onUnauthorized(rejectedKey: string): void {
  const account = listAccounts().find((a) => a.deviceKey === rejectedKey);
  // The rejected credential is no longer stored - it was already removed, or the person has moved on.
  // Nothing to revoke, and nothing to re-gate: acting here would remove an account on the strength of a
  // stale answer about a different one.
  if (!account) return;

  removeAccount(account.id);
  if (typeof window === "undefined") return;

  // A revoke takes out ONE account, not the browser (devthrottle_internal #1509). When another account
  // is still enrolled here, removeAccount has already made it the active one, so the honest landing is
  // that account's app - hand the cookie to it and reload in place. Sending a person who still holds a
  // working login to the sign-in screen would read as "you have been signed out" when they have not been.
  if (getDeviceKey()) {
    void adoptGatewayCookie();
    window.location.reload();
    return;
  }

  // No account left. The cookie cannot be cleared with a credential this browser no longer holds, so
  // this is best-effort - the Gateway rejected the key anyway, which is what made it worthless.
  void clearGatewayCookie();
  const target = resolveSignInTarget({
    pathname: window.location.pathname,
    search: window.location.search,
  });
  // Compare on the path only so a resolver that appends a query (the desktop next=) does not loop
  // when the browser is already sitting on the sign-in entry.
  const targetPath = target.split("?")[0];
  if (window.location.pathname !== targetPath) {
    window.location.assign(target);
  }
}

// Issue #2189: the server's OWN sentence for a failure, carried on the thrown error instead of being
// discarded at the throw site. Before this, every non-2xx became `new GatewayError(status, "POST x
// failed: 404")` - the Gateway had written a perfectly good reason into `{ error: ... }` and the client
// dropped it, so the user was shown nothing but a three-digit number.
export interface GatewayFailureDetail {
  /** The server's sentence, from `{ error }` / `{ detail }` / `{ message }`. Never a status number. */
  reason?: string;
  /** The server's machine-readable code, when it sent one (e.g. "director_stale"). */
  code?: string;
  /** The server said this is worth retrying. */
  retryable?: boolean;
}

export class GatewayError extends Error {
  readonly status: number;
  /** The server's own sentence for this failure, when it sent one. Never a status number. */
  readonly serverReason?: string;
  /** The server's machine-readable code, when it sent one. */
  readonly code?: string;
  /** True when retrying could plausibly succeed: the server said so, or the status class implies it. */
  readonly retryable: boolean;
  constructor(status: number, message: string, detail?: GatewayFailureDetail) {
    super(message);
    this.name = "GatewayError";
    this.status = status;
    this.serverReason = detail?.reason;
    this.code = detail?.code;
    // A server `retryable` flag is authoritative. Absent one, the transport statuses that mean "the
    // request never reached a healthy backend" are retryable by definition; a 4xx is the caller's own
    // request being wrong and retrying it unchanged cannot help.
    this.retryable = detail?.retryable
      ?? (status === 0 || status === 429 || status === 502 || status === 503 || status === 504);
  }

  /**
   * Build the error for a non-2xx response, READING the server's reason out of the body.
   *
   * Every `!res.ok` throw in this client must go through here. A bare `new GatewayError(res.status,
   * "POST x failed: " + res.status)` is exactly what deleted the reason in the first place (issue #2189):
   * the Gateway had written a usable sentence into `{ error }` and the throw site dropped it one hop from
   * being shown, leaving the user with three digits.
   *
   * It consumes the response body, which is safe BY CONSTRUCTION at every call site: this is only reached
   * on a non-2xx, where the alternative was discarding the body unread. The few call sites that parse an
   * error body themselves (create session, the transcription legs) build their own error and never come
   * here, so nothing reads a body twice.
   *
   * `what` names the action in the user's terms ("attach the image"), never the method and path.
   */
  static async from(res: Response, what: string): Promise<GatewayError> {
    const detail = await readFailureDetail(res);
    return new GatewayError(res.status, detail.reason ?? `Could not ${what} (error ${res.status}).`, detail);
  }
}

/** Pull the server's reason, code and retryable flag out of a failed response. Best-effort by
 *  construction: a body that is missing, empty, unreadable or not JSON yields an empty detail, and this
 *  must never turn a failed request into a thrown parse error. */
async function readFailureDetail(res: Response): Promise<GatewayFailureDetail> {
  try {
    const text = await res.text();
    if (!text.trim()) return {};
    try {
      const body = JSON.parse(text) as Record<string, unknown>;
      return {
        reason: stringFromErrorBody(body),
        code: typeof body.code === "string" ? body.code : undefined,
        retryable: typeof body.retryable === "boolean" ? body.retryable : undefined,
      };
    } catch {
      // A non-JSON body is still a reason, provided it is short enough to be a sentence rather than an
      // HTML error page from something in front of the Gateway.
      if (text.length <= 300 && !text.trimStart().startsWith("<")) return { reason: text.trim() };
      return {};
    }
  } catch {
    return {};
  }
}

// The shared "hosted AI is unavailable" body every money endpoint returns on HTTP 402 (issue #939/#941;
// consumed by mobile in #942): the single-source message + call-to-action. `text` is the message to show;
// `ctaUrl` deep-links to the call-to-action page when there is one.
export interface HostedAiUnavailable {
  state: string;      // "NeedsCredits" | "CapReached" | "NeedsKey" | "SubscriptionRequired" | "FairUseLimitReached" | "Unavailable"
  text: string;
  ctaLabel: string;
  ctaAction: string;  // "OpenBilling" | "OpenSettings" | "OpenPricing" | "None"
  ctaUrl: string | null;
}

// A 402 from a hosted-AI call. Its `message` IS the shared text, so any surface that already shows
// `err.message` displays the correct copy by construction; `info` carries the call-to-action for the
// app-level notice (issue #942). The fallback for a body with no text is NEUTRAL (issue #1360): a 402
// we cannot read must never claim the account is out of credits.
export class CreditsError extends GatewayError {
  readonly info: HostedAiUnavailable;
  constructor(info: HostedAiUnavailable) {
    super(402, info.text || "This AI feature is not available for your account right now.");
    this.name = "CreditsError";
    this.info = info;
  }
}

// App-level subscription so ONE notice (with the "Add credits" button) shows wherever a 402 happens,
// without every surface widening its string error state. The client emits on every hosted-AI 402; the
// app renders a single CreditsNotice. Returns an unsubscribe function.
type CreditsListener = (info: HostedAiUnavailable) => void;
const creditsListeners = new Set<CreditsListener>();
export function onCreditsNeeded(fn: CreditsListener): () => void {
  creditsListeners.add(fn);
  return () => { creditsListeners.delete(fn); };
}

// Build a CreditsError from an already-parsed 402 body and notify the app-level notice. Call from the
// `!res.ok` branch of any hosted-AI call when `res.status === 402` (the body is already the shared
// shape from the Gateway). The defaults for missing fields are NEUTRAL (issue #1360): a 402 whose body
// cannot be read is an unknown money-shaped refusal, and it must never claim the account is out of
// credits or offer a top-up button - the owner ruled a normal member sees no cost anywhere.
export function creditsErrorFrom(body: unknown): CreditsError {
  const b = (body ?? {}) as Partial<HostedAiUnavailable> & { error?: string };
  const info: HostedAiUnavailable = {
    state: b.state ?? "Unavailable",
    text: b.text ?? b.error ?? "This AI feature is not available for your account right now.",
    ctaLabel: b.ctaLabel ?? "",
    ctaAction: b.ctaAction ?? "None",
    ctaUrl: b.ctaUrl ?? null,
  };
  for (const fn of creditsListeners) { try { fn(info); } catch { /* a listener must never break the throw */ } }
  return new CreditsError(info);
}

// The single user-facing line for "the Gateway is unreachable", shared by every page that reads the
// Gateway on a poll (issue #1028). It implies the automatic retry those pages already perform, so the
// copy is truthful wherever it appears.
export const GATEWAY_UNREACHABLE_MESSAGE = "Can't reach the Gateway - retrying.";

// True when an error means the request never reached a healthy backend: the browser's bare fetch
// rejection when the Gateway is down (a TypeError, not a GatewayError), or a Gateway/proxy status
// that signals it could not reach the backend (Bad Gateway, Service Unavailable, Gateway Timeout, or
// a synthetic 0). These are the "unreachable" cases, distinct from a reachable Gateway that answered
// with an application error (400/404/409/500).
function isGatewayUnreachable(err: unknown): boolean {
  if (err instanceof GatewayError) {
    return err.status === 0 || err.status === 502 || err.status === 503 || err.status === 504;
  }
  return err instanceof Error;
}

// The header the Gateway stamps when a failure is the DIRECTOR's and not its own - it did not answer in
// time, or its tunnel died mid-command (issue #1153, TunnelCatchAllDispatch.FaultSideHeader).
const FAULT_SIDE_HEADER = "X-DevThrottle-Fault";
const FAULT_SIDE_DIRECTOR = "director";

// True when a 502/504 came from OUR Gateway, about a Director, rather than from an edge proxy in front of a
// Gateway that is down.
//
// WHY THIS EXISTS. 502/503/504 are read as "the backend could not be reached", which is right when they come
// from a proxy and wrong when the Gateway itself composed them to say a MACHINE behind it went quiet. Without
// this, one Director stalling for seven seconds put "Bad connection - showing last known information" on the
// owner's phone while the Gateway was answering him in the same millisecond - the app blaming the one part of
// the system that was working. A Director being slow is not a connection problem and must not be reported as
// one; the screen that asked for that machine's data still surfaces its own failure, and the Gateway's error
// body already names the machine in plain words.
//
// ABSENCE IS THE SAFE DEFAULT: a proxy in front of a dead Gateway cannot stamp this, so an unstamped 502
// still means unreachable, exactly as before. Only a stamped response is treated as proof the Gateway
// answered.
function isDirectorFault(res: Response): boolean {
  return res.headers.get(FAULT_SIDE_HEADER) === FAULT_SIDE_DIRECTOR;
}

// The ONE transport choke point every Gateway contact in this client routes through, so the shared
// connection-health signal (connection/health.ts) is fed in exactly one place instead of hand-wired
// into each page's poll. It is a transparent wrapper around the browser fetch: it returns the same
// Response and rethrows the same error, adding only a health report. An answered request whose status
// means the backend was unreachable (502/503/504, or a synthetic 0) reports UNREACHABLE; every other
// answered status - including 4xx/500 application errors - reports REACHABLE (the Gateway answered). A
// bare fetch rejection (the backend is down) reports UNREACHABLE. A caller-initiated abort is not a
// connection signal, so it is rethrown without any report. This mirrors the issue #1028 classification
// used by isGatewayUnreachable; it does not invent a second taxonomy. Exported so the fleet client
// (fleetClient.ts) routes its reads - including the roster envelope the mobile app now polls - through
// the SAME choke point, keeping the connection-health signal fed no matter which reader is on screen.
//
// timeoutMs (mobile-resilience mission, Phase 4): a hardening cap for the repeating POLL reads (the
// roster, chat history, voice). Without it a request that HANGS (a half-open connection on a flaky
// mobile network - the TCP never resets, so fetch neither resolves nor rejects) would sit in flight
// forever, so the health signal never flips to bad and the banner never shows. With it, a poll that
// exceeds the cap is aborted and reported UNREACHABLE (a timed-out request could not reach a healthy
// backend), distinct from a caller-initiated abort. One-shot writes pass no timeout and are unchanged.
export async function gatewayFetch(
  input: RequestInfo | URL,
  init?: RequestInit,
  opts?: { timeoutMs?: number },
): Promise<Response> {
  const timeoutMs = opts?.timeoutMs;
  const callerSignal = init?.signal ?? undefined;
  let controller: AbortController | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let timedOut = false;
  let onCallerAbort: (() => void) | undefined;
  let signal = callerSignal;
  if (timeoutMs !== undefined) {
    // Race the fetch against the timeout via our own controller, and forward a caller abort to it so
    // both an unmount and a timeout cancel the in-flight request.
    controller = new AbortController();
    signal = controller.signal;
    if (callerSignal) {
      if (callerSignal.aborted) controller.abort();
      else { onCallerAbort = () => controller!.abort(); callerSignal.addEventListener("abort", onCallerAbort, { once: true }); }
    }
    timer = setTimeout(() => { timedOut = true; controller!.abort(); }, timeoutMs);
  }

  let res: Response;
  try {
    res = await fetch(input, signal ? { ...init, signal } : init);
  } catch (err) {
    // A timeout is a connection failure (the request could not reach a healthy backend in time), so it
    // is reported and surfaced as an error rather than swallowed like a caller cancel.
    if (timedOut) {
      reportGatewayUnreachable();
      throw new GatewayError(504, "Gateway request timed out");
    }
    // A caller-initiated abort (the browser throws a DOMException named "AbortError", which extends
    // Error) is a cancel, not a connection signal - rethrow it without recording anything.
    if (err instanceof Error && err.name === "AbortError") throw err;
    reportGatewayUnreachable();
    throw err;
  } finally {
    if (timer !== undefined) clearTimeout(timer);
    if (onCallerAbort && callerSignal) callerSignal.removeEventListener("abort", onCallerAbort);
  }
  if ((res.status === 0 || res.status === 502 || res.status === 503 || res.status === 504) && !isDirectorFault(res)) {
    reportGatewayUnreachable();
  } else {
    reportGatewayReachable();
  }
  return res;
}

// The cap for the repeating poll reads (roster, chat history, voice). Long enough not to trip on a slow
// but alive mobile connection, short enough that a hung request surfaces as a bad connection within one
// or two poll cycles instead of never (mobile-resilience mission, Phase 4).
export const POLL_TIMEOUT_MS = 10000;

// Map any error thrown by a Gateway read/write into ONE user-facing line, never leaking the internal
// "METHOD /path failed: NNN" diagnostic the client throws on a non-2xx, nor the browser's bare
// "Failed to fetch" when the backend is down (issue #1028).
//
// THE RULE (issue #2189): a number is not an error message. Whatever this returns must say what
// happened, and say whether trying again is worth it. It may mention the status in parentheses for
// support purposes; the status may never BE the message. The old behaviour - everything that was not a
// 401 collapsing to "The Gateway rejected the request (error 404)." - is what left the user with three
// digits and nothing else after a failed image attach, on a session that was alive the whole time.
//
// Order of preference:
//  1. The server's own sentence, when it sent one (the Gateway writes good ones - see the retryable
//     "has not reported in for N seconds ... try again" copy on a stale Director).
//  2. Human copy already carried on the error (a 401 re-auth prompt, a 402 credits notice).
//  3. A plain sentence for the status class, naming the action when the caller supplied one.
//
// `what` names the action in the user's terms - "attach the image", "send the prompt". Optional so the
// many existing poll call sites keep compiling; supply it anywhere a person is watching.
export function gatewayErrorMessage(err: unknown, what?: string): string {
  if (err instanceof CreditsError) return err.message;
  if (err instanceof GatewayError) {
    // The server's reason wins over every generic line we could write here.
    if (err.serverReason) return withRetryHint(err.serverReason, err.retryable);
    if (err.status === 401) return err.message;
    // No reason from the server. A background POLL that could not reach the backend keeps the shared
    // line from issue #1028 - it is already a real sentence and it already implies the retry those
    // pages perform. Naming an action means a person pressed something and is waiting, so they get the
    // specific sentence instead.
    if (!what && isUnreachableStatus(err.status)) return GATEWAY_UNREACHABLE_MESSAGE;
    return withRetryHint(statusSentence(err.status, what), err.retryable);
  }
  if (isGatewayUnreachable(err)) return GATEWAY_UNREACHABLE_MESSAGE;
  return GATEWAY_UNREACHABLE_MESSAGE;
}

/** The statuses that mean the request never reached a healthy backend. */
function isUnreachableStatus(status: number): boolean {
  return status === 0 || status === 502 || status === 503 || status === 504;
}

/** Add the retry advice unless the reason already gives it, so a retryable failure always tells the
 *  user that trying again is the right move (and a permanent one never suggests it). */
function withRetryHint(sentence: string, retryable: boolean): string {
  if (!retryable) return sentence;
  if (/try again|retrying|retry/i.test(sentence)) return sentence;
  return `${sentence} Try again.`;
}

/** The fallback sentence when the server sent no reason of its own. Never a bare number. */
function statusSentence(status: number, what?: string): string {
  const action = what ? `could not ${what}` : "could not complete that";
  if (status === 0 || status === 502 || status === 503 || status === 504) {
    return `DevThrottle ${action} - the machine running this session could not be reached (error ${status}).`;
  }
  if (status === 404) {
    return `DevThrottle ${action} - the session could not be found (error 404). It may have been closed.`;
  }
  if (status === 409) {
    return `DevThrottle ${action} - something else changed it first (error 409). Reload and try again.`;
  }
  if (status === 413) {
    return `DevThrottle ${action} - the file is too large (error 413).`;
  }
  if (status === 423) {
    return `DevThrottle ${action} - this session is on hold (error 423). Take it off hold first.`;
  }
  if (status === 429) {
    return `DevThrottle ${action} - too many requests in a row (error 429).`;
  }
  if (status >= 500) {
    return `DevThrottle ${action} - the Gateway hit an internal error (error ${status}).`;
  }
  return `DevThrottle ${action} (error ${status}).`;
}

type GatewayErrorBody = {
  error?: unknown;
  reason?: unknown;
  detail?: unknown;
  message?: unknown;
  code?: unknown;
};

function stringFromErrorBody(body: unknown): string | undefined {
  if (typeof body === "string") return body;
  if (!body || typeof body !== "object") return undefined;
  const b = body as GatewayErrorBody;
  if (typeof b.error === "string") return b.error;
  if (b.error && typeof b.error === "object") {
    const nested = b.error as GatewayErrorBody;
    const message = typeof nested.message === "string" ? nested.message : undefined;
    const code = typeof nested.code === "string" ? nested.code : undefined;
    return [message, code].filter(Boolean).join(" ") || undefined;
  }
  // `reason` is the availability surfaces' spelling: the statistics feed answers
  // `{ available: false, reason }` on 503, and the Gateway writes a full operator-facing sentence into it.
  // It was NOT read here, and the cost was an incident (devthrottle_internal, 2 September 2026). With no
  // reason found, a 503 falls through to the unreachable-status branch in gatewayErrorMessage and Your
  // Throttle rendered "Can't reach the Gateway - retrying." for hours - pointing at a dead Gateway that was
  // healthy the whole time and serving every other page, while the true sentence ("the statistics store
  // could not be reached") sat unread in the body. A reason the server took the trouble to write must never
  // lose to a sentence we invent from a status number.
  if (typeof b.reason === "string") return b.reason;
  if (typeof b.detail === "string") return b.detail;
  if (typeof b.message === "string") return b.message;
  if (typeof b.code === "string") return b.code;
  return undefined;
}

async function readGatewayErrorBody(res: Response): Promise<string | undefined> {
  const text = await res.text().catch(() => "");
  if (!text.trim()) return undefined;
  try {
    return stringFromErrorBody(JSON.parse(text)) ?? text;
  } catch {
    return text;
  }
}

// GET /sessions - the fleet roster aggregator. Returns the same SessionDto shape the Cockpit
// Mobile page consumes. Throws GatewayError on a non-2xx so the caller surfaces it (no silent
// fallback). The request is same-origin against the Gateway front door.
export async function listSessions(signal?: AbortSignal): Promise<SessionDto[]> {
  // Captured BEFORE the request, so a 401 arriving after the active account has moved on can be
  // attributed to the credential that was actually rejected.
  const rejected = getDeviceKey();
  const res = await gatewayFetch("/sessions", {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  }, { timeoutMs: POLL_TIMEOUT_MS });
  if (res.status === 401) {
    // The device key was revoked (or is otherwise invalid): forget it and re-gate to Sign in. The
    // roster is the first credentialed call the app makes, so this is where a revoke surfaces.
    // The key THIS request was sent with is passed in - see onUnauthorized for why the active one at
    // response time is the wrong thing to delete.
    onUnauthorized(rejected);
    throw new GatewayError(res.status, "This device is no longer authorized. Please sign in again.");
  }
  if (!res.ok) {
    throw await GatewayError.from(res, "load the session list");
  }
  return (await res.json()) as SessionDto[];
}

// GET /sessions/{sid}/history - the parsed, agent-agnostic conversation history for one session
// (issue #811). The Director's SessionHistoryEndpoint returns SessionHistoryDto; the Gateway
// forwards it verbatim through the catch-all /sessions/{sid}/{**rest} proxy with the injected
// Bearer (no backend change), exactly the way Terminal reaches /prompt. The shape is not declared
// in the OpenAPI schema (it rides the generic per-session proxy), so it is read with the narrow
// local SessionHistoryDto type. A 404 (old Director / unknown session) is surfaced as a
// GatewayError so the caller can treat it as "nothing yet" rather than a hard failure.
export async function getSessionHistory(
  sessionId: string,
  signal?: AbortSignal,
): Promise<SessionHistoryDto> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/history`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  }, { timeoutMs: POLL_TIMEOUT_MS });
  if (!res.ok) {
    throw await GatewayError.from(res, "load the conversation history");
  }
  return (await res.json()) as SessionHistoryDto;
}

// Write text (or a raw key escape sequence) to the session's PTY. appendEnter=true submits a typed
// line (the Send button); appendEnter=false writes the bytes verbatim (Enter "\r", arrow keys
// A composer's spoken ranges as the wire carries them: only spans that name a transcript the Gateway can
// verify are worth sending, so a span with no id is dropped here rather than refused there.
function spokenSpanClaims(spans?: readonly SpokenSpan[]): { start: number; length: number; transcriptId: string }[] {
  if (spans === undefined) return [];
  return spans
    .filter((s) => s.transcriptId !== undefined && s.transcriptId !== "" && s.length > 0)
    .map((s) => ({ start: s.start, length: s.length, transcriptId: s.transcriptId as string }));
}

// ESC[A/B/C/D) so the session reacts as if the key were pressed at the terminal.
// `spokenDeliveryId` says this text was SPOKEN, not typed: it is the id of the utterance the Gateway
// just transcribed, handed back by transcribeUtterance and passed straight through here. Without it a
// dictated sentence submitted through this door is recorded as typed, because the Director reads the
// modality off the send source and an ordinary prompt is a typed one - so the same words counted as
// spoken or typed purely by which transcription path the surface happened to use. Ruling R10 of the
// "Clean up Your Throttle" mission (2026-09-05).
//
// Pass it ONLY when the submitted text is the dictation and nothing else. A caller that mixed typed
// text into the box before sending must leave it out: that turn is not wholly spoken, and the page's
// own disclosure already says a transcript sent alongside typed text counts as typed.
export async function sendPrompt(
  sessionId: string,
  text: string,
  appendEnter: boolean,
  signal?: AbortSignal,
  spokenDeliveryId?: string,
  spokenSpans?: readonly SpokenSpan[],
): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const body: PromptRequest = { text, appendEnter };
  if (spokenDeliveryId) body.deliveryUploadId = spokenDeliveryId;
  // WHICH characters were spoken, when the composer tracked them (source logging, 2026-09-05). Sent whether
  // or not the turn is wholly spoken: a turn typed around a dictation is TYPED, and still says which of its
  // characters came from a microphone. Claims, not facts - the Gateway verifies each against the transcript
  // it registered and drops any it cannot.
  const claims = spokenSpanClaims(spokenSpans);
  if (claims.length > 0) body.spokenSpans = claims;
  const res = await gatewayFetch(`/sessions/${sid}/prompt`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
    body: JSON.stringify(body),
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "send that to the session");
  }
}

// What a session's live screen is right now (GET /sessions/{sid}/wingman/waiting-screen). "menu" means a
// chooser owns the screen and typing into it is meaningless; "text" is an ordinary composer; "blocked" is a
// screen the Gateway could not positively read. Cheap on the Gateway - one terminal read, no model call.
export interface WaitingScreen {
  kind: "menu" | "text" | "blocked";
  /** False ONLY on "menu" - phase 1 refuses on a recognized menu and nothing else. */
  canType: boolean;
  /** The line to speak when a menu is blocking; empty otherwise. */
  spoken: string;
  /** The language `spoken` is in, as the code the Gateway decided ("en"/"fr"/"es") - issue #1031. The caller
   *  builds a SpokenUtterance from the pair, and cannot build one without this. */
  spokenLanguage: string;
  /** The line to show on screen when a menu is blocking; empty otherwise. */
  message: string;
}

export async function getWaitingScreen(sessionId: string, signal?: AbortSignal): Promise<WaitingScreen> {
  const sid = encodeURIComponent(sessionId);
  // Hard-capped on purpose. The fire-and-forget voice Send asks this BEFORE it hands the recording to the
  // durable background pipeline, so a slow answer here would hold a clip that exists only in memory. A
  // check that cannot finish promptly is not worth a recording - the read gives up and the reply proceeds.
  const res = await gatewayFetch(`/sessions/${sid}/wingman/waiting-screen`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  }, { timeoutMs: POLL_TIMEOUT_MS });
  if (!res.ok) {
    throw new GatewayError(res.status, `GET wingman/waiting-screen failed: ${res.status}`);
  }
  const body = (await res.json()) as Partial<WaitingScreen>;
  const kind = body.kind === "menu" || body.kind === "text" ? body.kind : "blocked";
  return {
    kind,
    canType: kind !== "menu",
    spoken: body.spoken ?? "",
    spokenLanguage: body.spokenLanguage ?? "",
    message: body.message ?? "",
  };
}

// The outcome of a voice reply: either it went into the session, or a menu owned the screen and the Gateway
// refused to type it. A refusal is a NORMAL outcome, not an error - the caller asked for exactly this - so it
// comes back as a value rather than a thrown GatewayError.
export interface VoicePromptResult {
  sent: boolean;
  blockedByMenu: boolean;
  /** The line to speak on a refusal; empty when the prompt was sent. */
  spoken: string;
  /** The language `spoken` is in, as the code the Gateway decided ("en"/"fr"/"es") - issue #1031. The caller
   *  builds a SpokenUtterance from the pair, and cannot build one without this. */
  spokenLanguage: string;
  /** The line to show on a refusal; empty when the prompt was sent. */
  message: string;
}

// Send a spoken reply into the session WITH the menu guard on (POST /sessions/{sid}/prompt, menuGuard).
// The Gateway reads the live screen one hop before the send: if a chooser owns it, nothing is typed and no
// Enter is pressed - which matters because the Enter this call carries would otherwise confirm whichever
// option the picker had highlighted. Only the voice reply paths use this; every typed-composer send stays on
// the plain sendPrompt above, completely unchanged.
export async function sendVoicePrompt(
  sessionId: string,
  text: string,
  signal?: AbortSignal,
  spokenDeliveryId?: string,
  spokenSpans?: readonly SpokenSpan[],
): Promise<VoicePromptResult> {
  const sid = encodeURIComponent(sessionId);
  const body: PromptRequest & { menuGuard: boolean } = { text, appendEnter: true, menuGuard: true };
  const claims = spokenSpanClaims(spokenSpans);
  if (claims.length > 0) body.spokenSpans = claims;
  // A voice-mode reply is speech by definition, yet it reaches the session as an ordinary prompt, and
  // the Director reads modality off the send source - so without the delivery id it was recorded as
  // TYPED. Passed through, never invented here: the dialog withholds it the moment the words stop
  // being one unedited transcription. Ruling R10, "Clean up Your Throttle" (2026-09-05).
  if (spokenDeliveryId) body.deliveryUploadId = spokenDeliveryId;
  const res = await gatewayFetch(`/sessions/${sid}/prompt`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
    body: JSON.stringify(body),
    signal,
  });
  if (!res.ok) {
    throw new GatewayError(res.status, `POST prompt failed: ${res.status}`);
  }
  const answer = (await res.json()) as {
    accepted?: boolean;
    blockedByMenu?: boolean;
    blockedSpoken?: string;
    blockedSpokenLanguage?: string;
    error?: string;
  };
  if (answer.blockedByMenu === true) {
    return {
      sent: false,
      blockedByMenu: true,
      spoken: answer.blockedSpoken ?? "",
      spokenLanguage: answer.blockedSpokenLanguage ?? "",
      message: answer.error ?? "",
    };
  }
  return { sent: true, blockedByMenu: false, spoken: "", spokenLanguage: "", message: "" };
}

// Soft-stop the current turn (the agent driver's Escape). POST /sessions/{sid}/escape.
export async function sendEscape(sessionId: string, signal?: AbortSignal): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/escape`, {
    method: "POST",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "send Escape to the session");
  }
}

// Interrupt a running agent turn (Ctrl+C). POST /sessions/{sid}/interrupt.
export async function sendInterrupt(sessionId: string, signal?: AbortSignal): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/interrupt`, {
    method: "POST",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "interrupt the session");
  }
}

// Reset the conversation context in place (/clear for Claude, /new for pi) without ending the
// process. POST /sessions/{sid}/clear-context. Only meaningful for drivers that declare the
// ClearContext capability; the caller gates the button on SessionDto.driverCapabilities.
export async function sendClearContext(sessionId: string, signal?: AbortSignal): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/clear-context`, {
    method: "POST",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "clear the session context");
  }
}

/**
 * What POST /sessions/{sid}/compact-context answers (issue #2150). Mirrors the Gateway's
 * CompactContextResponse; hand-declared here because the checked-in OpenAPI schema is regenerated at
 * build time and does not carry this route yet.
 */
export interface CompactContextResult {
  /** The compaction command reached the tool. */
  submitted: boolean;
  /**
   * The tool's own records confirm the compaction FINISHED. False means it was submitted and not
   * watched - a stated limit of that tool, not a failure. Never render this case as "compacted".
   */
  compactionObserved: boolean;
  /** Seconds between submitting and seeing it finish; 0 when not watched. */
  waitedSeconds: number;
  /** The follow-up prompt was submitted after the compaction finished. */
  continued: boolean;
  /** One plain-English sentence describing what happened. Render it verbatim. */
  detail: string;
}

/**
 * How long the client waits for a compaction. A compaction is a language model summarizing a whole
 * conversation and routinely runs past a minute; the Gateway allows three, and the Director's own wait
 * is two. This sits OUTSIDE all of them so the innermost bound always fires first and reports what
 * actually failed - a client that gave up sooner would report a failure over a compaction that was
 * working perfectly, which is the exact false alarm this feature exists to remove.
 */
export const COMPACT_CONTEXT_TIMEOUT_MS = 4 * 60 * 1000;

/**
 * Summarize the conversation in place, freeing context window while keeping what the session has
 * learned, and optionally send a follow-up once it FINISHES. POST /sessions/{sid}/compact-context.
 *
 * Distinct from sendClearContext, which throws the conversation away. Gate the button on the
 * CompactContext capability; only pass continuePrompt when the driver also declares
 * CompactCompletionReport, because the Gateway refuses a continuation it cannot time.
 */
export async function sendCompactContext(
  sessionId: string,
  continuePrompt?: string,
  signal?: AbortSignal,
): Promise<CompactContextResult> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(
    `/sessions/${sid}/compact-context`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
      body: JSON.stringify(continuePrompt ? { continuePrompt } : {}),
      signal,
    },
    { timeoutMs: COMPACT_CONTEXT_TIMEOUT_MS },
  );
  if (!res.ok) {
    throw await GatewayError.from(res, "compact the session context");
  }
  return (await res.json()) as CompactContextResult;
}

// Open the tool's in-terminal history / rewind picker (Claude's double-Esc). POST
// /sessions/{sid}/history-picker. Gated on the History capability - a visible-terminal feature.
export async function sendHistoryPicker(sessionId: string, signal?: AbortSignal): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/history-picker`, {
    method: "POST",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "open the history picker");
  }
}

// ===== Prompt queue (issue #972): the composer's Queue and the queue panel verbs =====
// A faithful port of the Blazor Cockpit DirectorClient queue methods. Every verb returns the
// server's authoritative queue (the owning Director owns the ordered list), so the caller
// replaces its whole list from the response rather than mutating optimistically. All routes are
// root-relative to the Gateway, which forwards the session-scoped verb to the owning Director.

/** One queued prompt, as returned by GET /sessions/{sid}/queue on a Director. */
export interface QueueItem {
  id: string;
  text: string;
  /** ISO 8601 UTC when the item was queued. */
  createdAt: string;
}

// Read the response's { items } as the authoritative queue. Shared by every queue verb so the
// parse lives in one place; a non-2xx throws so the caller surfaces it (no silent empty queue).
// `what` names the action for the user (issue #2189), so a failed queue verb reads as "DevThrottle
// could not queue that prompt", never as a status number.
async function readQueue(res: Response, what: string): Promise<QueueItem[]> {
  if (!res.ok) {
    throw await GatewayError.from(res, what);
  }
  const body = (await res.json().catch(() => ({}))) as { items?: QueueItem[] };
  return body.items ?? [];
}

// GET /sessions/{sid}/queue - the session's current queued prompts, in order.
export async function getQueue(sessionId: string, signal?: AbortSignal): Promise<QueueItem[]> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/queue`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  return readQueue(res, "load the prompt queue");
}

// ===== Source control (issue #1266) =====

/** One changed file in a session's repository, as returned by GET /sessions/{sid}/git. */
export interface GitChangeEntry {
  /** Repository-relative path of the changed file. */
  path: string;
  /** One-letter git change kind: "M" modified, "A" added, "D" deleted, "R" renamed, "C" copied, "?" untracked. */
  changeKind: string;
}

/**
 * A read-only snapshot of a session repository's source-control state (GET /sessions/{sid}/git).
 * `status` is "ok" | "not_a_repo" | "git_failed"; on a non-ok status `error` carries the detail and
 * the change lists are empty. The lists are additive fields the read endpoint fills for the Source
 * Control tab.
 */
export interface GitSnapshot {
  branch: string;
  dirty: boolean;
  ahead: number;
  behind: number;
  lastCommit: string;
  status: string;
  error?: string | null;
  stagedChanges: GitChangeEntry[];
  unstagedChanges: GitChangeEntry[];
}

// GET /sessions/{sid}/git - the read-only source-control snapshot for a session's repository. A non-2xx
// throws so the caller surfaces it (no silent empty state); a non-ok `status` in the body is a normal
// result the caller renders ("not a git repository" / "git failed"), not an error.
export async function getGitStatus(sessionId: string, signal?: AbortSignal): Promise<GitSnapshot> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/git`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "read the repository status");
  }
  const body = (await res.json()) as GitSnapshot;
  return {
    ...body,
    stagedChanges: body.stagedChanges ?? [],
    unstagedChanges: body.unstagedChanges ?? [],
  };
}

