// ===== Screenshots gallery (issue #972): the captured-screenshots folder on the owning Director =====
// A faithful port of the Blazor DirectorClient screenshots methods. The folder is per-machine on the
// Director, but the Cockpit always asks in the context of the selected session, so the session id is
// the routing key and the Gateway forwards to the owning Director's machine-wide folder. The image
// BYTES are loaded by the browser same-origin through the Gateway's per-session proxy
// (screenshotFileUrl), so no absolute Director address ever reaches the page (issue #317 / #967).

/** One screenshot on a Director's machine. The Director pre-formats timeLabel so every surface
 *  shows the same label without re-deriving it. */
export interface ScreenshotInfo {
  fileName: string;
  /** Absolute on-disk path on the Director's machine, injected into the composer so the owning
   *  agent can read the image directly (no upload). */
  path: string;
  timeLabel: string;
  lastWriteUtc: string;
  sizeBytes: number;
}

/** GET /sessions/{sid}/screenshots: the resolved folder + its newest image files. */
export interface ScreenshotsResult {
  directory: string;
  /** Full folder count regardless of any count cap; 0 on old Directors (treat items.length as total). */
  total: number;
  items: ScreenshotInfo[];
}

// The same-origin URL for a screenshot's bytes, used as the thumbnail <img src> and the "view
// full size" link. Root-relative to the Gateway (never a Director address), so a Director that
// advertises only a loopback endpoint still renders correctly for a remote browser (issue #317).
export function screenshotFileUrl(sessionId: string, fileName: string): string {
  const sid = encodeURIComponent(sessionId);
  return `/sessions/${sid}/screenshots/file?name=${encodeURIComponent(fileName)}`;
}

// ===== Local Files (remote file viewer): any local file on the owning Director's disk =====
// Same request shape as the screenshot bytes above, generalized from "one screenshot" to "any file
// by absolute path". The client viewing a session always has the session id, so it asks the Gateway
// same-origin at /sessions/{sid}/file?path=... ; the Gateway's per-session catch-all resolves the
// owning Director and forwards the request there, and the Director streams the bytes off its own
// disk. The session id is purely the routing vehicle that reaches the right machine (the path is
// always a path on that machine), not a sandbox. Root-relative to the Gateway, so a browser <img>
// or <iframe> src carries the cc-gateway-token cookie exactly as the screenshot viewer does.

/** The same-origin URL for a local file's bytes on the owning Director, used as an <img>/<iframe>
 *  src and as the target of a Download link. `path` is an absolute path on the session's machine. */
export function sessionFileUrl(sessionId: string, path: string): string {
  const sid = encodeURIComponent(sessionId);
  return `/sessions/${sid}/file?path=${encodeURIComponent(path)}`;
}

// Fetch a local file's TEXT content through the Gateway (for the Markdown and text/code viewers,
// which need the string, not an <img>/<iframe> src). A non-OK response is thrown as a GatewayError
// so the viewer can show the real reason - 404 for a missing file, 503 for an offline Director -
// never a silent blank.
export async function fetchSessionFileText(sessionId: string, path: string, signal?: AbortSignal): Promise<string> {
  const res = await gatewayFetch(sessionFileUrl(sessionId, path), {
    method: "GET",
    headers: { ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "open that file");
  }
  return res.text();
}

// The on-disk SIZE of a file on the owning Director, for the download panel's "name - size" display
// (Local Files, Phase 4). We do NOT download the file to weigh it: a Range: bytes=0-0 request makes the
// Director - which already serves this route with enableRangeProcessing on - answer 206 Partial Content
// with a Content-Range header ("bytes 0-0/<total>") whose total is the full size, transferring a single
// byte. This reuses the existing range support and needs no new server or Gateway route (the per-session
// catch-all proxy forwards any verb/headers unchanged). A missing file or offline machine is thrown as a
// GatewayError (404 / 503) so the panel can fail loud. When the total cannot be read - an old or odd
// server that ignored the range and returned 200 - null is returned and the caller shows the name and
// Download with NO guessed size (the brief's "no fake size" rule; no fallback programming).
export async function fetchSessionFileSize(sessionId: string, path: string, signal?: AbortSignal): Promise<number | null> {
  const res = await fetch(sessionFileUrl(sessionId, path), {
    method: "GET",
    headers: { ...authHeaders(), Range: "bytes=0-0" },
    signal,
  });
  // 206 (range honored) and 200 (range ignored, full body) are both "ok"; anything else is a real error.
  if (!res.ok) {
    throw await GatewayError.from(res, "read that file's size");
  }
  // We never read the body - drop it so a 200 (full-file) response does not stream needlessly.
  void res.body?.cancel();
  const contentRange = res.headers.get("Content-Range");
  if (contentRange) {
    // "bytes 0-0/<total>" - the number after the last slash is the full file size.
    const slash = contentRange.lastIndexOf("/");
    if (slash >= 0) {
      const total = Number(contentRange.slice(slash + 1).trim());
      if (Number.isFinite(total) && total >= 0) return total;
    }
  }
  return null;
}

// GET /sessions/{sid}/screenshots[?count=N] - the newest screenshots' metadata (not the bytes).
// count <= 0 fetches everything (the folder can hold thousands, so callers pass a cap). A 503 means
// the owning Director is offline (the Gateway could not reach it for this leg, issue #412); it is
// surfaced as a GatewayError so the caller can show a graceful "Director offline" state + Retry.
export async function getScreenshots(sessionId: string, count = 0, signal?: AbortSignal): Promise<ScreenshotsResult> {
  const sid = encodeURIComponent(sessionId);
  const path = count > 0 ? `/sessions/${sid}/screenshots?count=${count}` : `/sessions/${sid}/screenshots`;
  const res = await gatewayFetch(path, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "load the screenshots");
  }
  const body = (await res.json().catch(() => ({}))) as Partial<ScreenshotsResult>;
  return {
    directory: body.directory ?? "",
    total: Number(body.total ?? 0),
    items: body.items ?? [],
  };
}

// DELETE /sessions/{sid}/screenshots/file?name=... - delete one screenshot file from the Director's disk.
export async function deleteScreenshot(sessionId: string, fileName: string, signal?: AbortSignal): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/screenshots/file?name=${encodeURIComponent(fileName)}`, {
    method: "DELETE",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "delete that screenshot");
  }
}

// POST /sessions/{sid}/upload-image (multipart, field "file") - forward a device-local image to the
// owning Director, which saves it to its Screenshots folder and returns the absolute on-disk path.
// The caller inserts that path into the composer so the agent can read the image directly; the
// upload endpoint itself injects nothing into the session.
export async function uploadImage(sessionId: string, file: File, signal?: AbortSignal): Promise<string> {
  const sid = encodeURIComponent(sessionId);
  const form = new FormData();
  form.append("file", file, file.name);
  const res = await gatewayFetch(`/sessions/${sid}/upload-image`, {
    method: "POST",
    headers: { ...authHeaders() },
    body: form,
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "attach the image");
  }
  const body = (await res.json().catch(() => ({}))) as { path?: string };
  return body.path ?? "";
}

// GET /sessions/{sid}/handover (issue #1214): the desktop app's "Handover info" identity block for a
// session - what a person or another agent needs to locate the session and talk to it. Mirrors the
// desktop "Copy Handover Info" block, minus the Director's Control API endpoint (the browser talks only
// to the Gateway and never learns a Director address). Not declared in the generated OpenAPI schema
