// ===== Session management (issue #812): the add-session flow + Hold/Resume + Remove =====
// A faithful 1:1 of the Android (MAUI) phone/CcDirectorClient "+ New session" flow and the
// owner's Hold/Remove decision. Every call carries the same Bearer the rest of the client uses, so
// the whole flow works with global Gateway auth on or off.

// GET /healthz - the running Gateway's own status and version. No auth needed. Backs the mobile
// About screen so the user can confirm which build they are on.
export async function getGatewayHealth(signal?: AbortSignal): Promise<GatewayHealth> {
  const res = await gatewayFetch("/healthz", {
    method: "GET",
    headers: { Accept: "application/json" },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "reach the Gateway");
  }
  return (await res.json()) as GatewayHealth;
}

// ===== Network diagnostics (auto-network-switching mission) =====
// Back the mobile Diagnostics page. A phone cannot run `tailscale ping`, so these let it measure the
// phone-to-Gateway path from the phone itself: which route it is on (direct LAN vs relayed through
// Tailscale), the round-trip latency, and the download/upload throughput.

/** GET /diag/echo - what the Gateway sees about THIS connection. clientPath is "tailscale" | "lan" | "local" | "other". */
export interface NetDiagEcho {
  clientIp: string | null;
  clientPath: string;
  forwardedFor: string;
  host: string;
  machineName: string;
  gatewayLanIp: string | null;
  gatewayTailnetName: string | null;
  serverTime: string;
}

// GET /diag/echo - the IP and host the Gateway sees for this request. RemoteIpAddress reflects
// X-Forwarded-For on the Gateway, so clientPath is the one clean signal that distinguishes a direct-LAN
// hit from a Tailscale relay. Gated like the rest of the data API, so it carries the per-device key.
export async function getNetDiagEcho(signal?: AbortSignal): Promise<NetDiagEcho> {
  const res = await gatewayFetch("/diag/echo", {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  }, { timeoutMs: POLL_TIMEOUT_MS });
  if (!res.ok) throw await GatewayError.from(res, "run the echo check");
  return (await res.json()) as NetDiagEcho;
}

/** One throughput measurement: bytes moved, milliseconds taken, and the derived megabits per second. */
export interface ThroughputResult {
  bytes: number;
  ms: number;
  mbps: number;
}

function megabitsPerSecond(bytes: number, ms: number): number {
  if (ms <= 0) return 0;
  return (bytes * 8) / (ms / 1000) / 1_000_000;
}

// Measure round-trip latency: fire `samples` tiny GET /diag/echo requests back to back and return each
// timing in milliseconds. Sequential (not parallel) so every number is a clean single-request round trip -
// the same thing the user feels tapping through the app. Stops early if the caller aborts.
export async function measureLatency(samples: number, signal?: AbortSignal): Promise<number[]> {
  const timings: number[] = [];
  for (let i = 0; i < samples; i++) {
    if (signal?.aborted) break;
    const t0 = performance.now();
    // /diag/ping is featherweight (no address lookup), so this measures wire time, not server work.
    const res = await gatewayFetch("/diag/ping", {
      method: "GET",
      headers: { Accept: "application/json", ...authHeaders() },
      signal,
    });
    await res.arrayBuffer(); // drain the body so the timing spans the whole round trip
    timings.push(performance.now() - t0);
  }
  return timings;
}

// Measure DOWNLOAD throughput: fetch `bytes` of incompressible data from the Gateway and time the whole
// transfer. The payload is no-store on the server, so the service worker never serves a cached copy that
// would fake the number.
export async function measureDownload(bytes: number, signal?: AbortSignal): Promise<ThroughputResult> {
  const t0 = performance.now();
  const res = await gatewayFetch(`/diag/payload?bytes=${bytes}`, {
    method: "GET",
    headers: { ...authHeaders() },
    signal,
  });
  if (!res.ok) throw await GatewayError.from(res, "run the download check");
  const buf = await res.arrayBuffer();
  const ms = performance.now() - t0;
  return { bytes: buf.byteLength, ms, mbps: megabitsPerSecond(buf.byteLength, ms) };
}

// Measure UPLOAD throughput: POST `bytes` of data and time it. Upload is the direction that carries
// dictation audio, so it is worth measuring on its own - a relay can be asymmetric.
export async function measureUpload(bytes: number, signal?: AbortSignal): Promise<ThroughputResult> {
  const body = new Uint8Array(bytes); // zero-filled is fine; we are timing the wire, not inspecting content
  const t0 = performance.now();
  const res = await gatewayFetch("/diag/payload", {
    method: "POST",
    headers: { "Content-Type": "application/octet-stream", ...authHeaders() },
    body,
    signal,
  });
  if (!res.ok) throw await GatewayError.from(res, "run the upload check");
  await res.arrayBuffer();
  const ms = performance.now() - t0;
  return { bytes, ms, mbps: megabitsPerSecond(bytes, ms) };
}

/** One connected device's live Tailscale path, from GET /diag/network. */
export interface NetDiagPeer {
  name: string;
  tailscaleIp: string | null;
  os: string | null;
  online: boolean;
  /** true = direct LAN/peer path, false = relayed through DERP, null = not determined. */
  direct: boolean | null;
  /** "192.168.x.y:port" when direct, or "DERP(region)" when relayed. */
  path: string | null;
  latencyMs: number | null;
  note: string | null;
}

/** GET /diag/network - the server-side Tailscale diagnostic (direct-vs-relay per device, no phone needed). */
export interface NetworkDiag {
  tailscaleAvailable: boolean;
  backendState: string | null;
  selfName: string | null;
  selfTailscaleIp: string | null;
  udpOk: boolean | null;
  mappingVariesByDestIp: boolean | null;
  nearestDerp: string | null;
  peers: NetDiagPeer[];
  notes: string[];
  collectedAt: string;
  /** The Gateway's finished status-pill ruling. Clients render every field verbatim. */
  connectionVerdict: {
    level: "green" | "amber" | "red" | "grey";
    label: string;
    detail: string;
  };
}

// Keep-warm heartbeat (Network Diagnostics mission, P2): a lightweight GET /diag/ping that keeps the
// WireGuard direct path from idling out during active foreground use (an idle path silently drops back to
// the relay until Tailscale re-establishes direct on the next request). Best-effort - a failure is ignored,
// this is NOT a reachability signal and must never surface an error.
export async function keepWarmPing(signal?: AbortSignal): Promise<void> {
  try {
    const res = await gatewayFetch("/diag/ping", { method: "GET", headers: { ...authHeaders() }, signal });
    await res.arrayBuffer();
  } catch {
    /* best-effort: keep-warm never reports failure */
  }
}

// GET /diag/network - the Gateway's finished connection verdict. On self-hosted Gateways the response also
// carries the server-side Tailscale check and can therefore take longer; on hosted it performs no shell work.
export async function getNetworkDiag(signal?: AbortSignal): Promise<NetworkDiag> {
  const res = await gatewayFetch("/diag/network", {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  }, { timeoutMs: 20000 });
  if (!res.ok) throw await GatewayError.from(res, "run the network check");
  return (await res.json()) as NetworkDiag;
}

/** A completed speed-test result, as submitted to POST /diag/result and returned by GET /diag/results. */
export interface NetDiagResult {
  route: string;
  latencyMedianMs: number | null;
  latencyBestMs: number | null;
  latencySamples: number;
  downloadMbps: number | null;
  uploadMbps: number | null;
  rating: string;
  verdict: string;
  loadedFrom: string;
  surface: string;
  /** Actual-path tags (from the authoritative self-peer): decide the home(LAN-direct)/away(relay) sub-sum. */
  direct?: boolean | null;
  isLanPath?: boolean;
  clientIp?: string | null;
  clientPath?: string | null;
  receivedAt?: string;
}

// POST /diag/result - hand the Gateway the result the page just computed so it is logged and readable by
// an agent at GET /diag/results. Best-effort: a failure here must never break the page, so callers treat a
// rejection as non-fatal (the numbers are still on screen).
export async function postNetDiagResult(result: NetDiagResult, signal?: AbortSignal): Promise<void> {
  const res = await gatewayFetch("/diag/result", {
    method: "POST",
    headers: { "Content-Type": "application/json", ...authHeaders() },
    body: JSON.stringify(result),
    signal,
  });
  if (!res.ok) throw await GatewayError.from(res, "record the check result");
}

// GET /diag/results - recent logged results, newest first. Backs the Cockpit history view and lets an
// agent read what users have been seeing.
export async function getNetDiagResults(signal?: AbortSignal): Promise<NetDiagResult[]> {
  const res = await gatewayFetch("/diag/results", {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  }, { timeoutMs: POLL_TIMEOUT_MS });
  if (!res.ok) throw await GatewayError.from(res, "load the check results");
  return (await res.json()) as NetDiagResult[];
}

/** One UTC-hour quality bucket from GET /diag/rollup, with the home(LAN)/away(relay) sub-sums. */
export interface NetDiagRollupBucket {
  hour: string;
  count: number;
  sumLatencyMs: number;
  minLatencyMs: number | null;
  directCount: number;
  relayCount: number;
  lanCount: number;
  sumLatencyLan: number;
  minLatencyLan: number | null;
  sumDownLan: number;
  sumUpLan: number;
  awayCount: number;
  sumLatencyAway: number;
  minLatencyAway: number | null;
  sumDownAway: number;
  sumUpAway: number;
}

// GET /diag/rollup - the hourly quality trend (oldest first) for the Cockpit dashboard. Sums, not
// averages: derive percent-direct = directCount/(directCount+relayCount) and avg latency = sum/count on read.
export async function getNetDiagRollup(signal?: AbortSignal): Promise<NetDiagRollupBucket[]> {
  const res = await gatewayFetch("/diag/rollup", {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  }, { timeoutMs: POLL_TIMEOUT_MS });
  if (!res.ok) throw await GatewayError.from(res, "load the network summary");
  return (await res.json()) as NetDiagRollupBucket[];
}

// GET /directors - the fleet's machines (Directors). Sorted most-recently-seen first so the picker
// can default-select the top one (matching FleetParser.ParseDirectors), tie-broken by machine name.
// Entries with no directorId are dropped (they cannot be addressed). Throws GatewayError on non-2xx
// so the picker shows the real reason instead of a silently empty list.
export async function getDirectors(signal?: AbortSignal): Promise<DirectorInfo[]> {
  const res = await gatewayFetch("/directors", {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "load the machine list");
  }
  const raw = (await res.json()) as Array<Record<string, unknown>>;
  const list: DirectorInfo[] = raw
    .map((d) => ({
      directorId: String(d.directorId ?? ""),
      machineName: String(d.machineName ?? ""),
      displayName: String(d.displayName ?? ""),
      version: String(d.version ?? ""),
      startedAt: String(d.startedAt ?? ""),
      lastSeen: String(d.lastSeen ?? ""),
      controlEndpoint: String(d.controlEndpoint ?? ""),
    }))
    .filter((d) => d.directorId.length > 0);
  list.sort((a, b) => {
    const bySeen = b.lastSeen.localeCompare(a.lastSeen); // newest-seen first (ISO 8601 sorts lexically)
    if (bySeen !== 0) return bySeen;
    return a.machineName.localeCompare(b.machineName);
  });
  return list;
}

// GET /directors/{id}/repos - a machine's recently-used repositories, sorted newest-used first
// (the server already sorts this way; we re-sort so a mixed body is still correct, matching
// FleetParser.ParseRepos). Entries with no path are dropped. Throws GatewayError on non-2xx.
export async function getRepos(directorId: string, signal?: AbortSignal): Promise<RepoInfo[]> {
  const id = encodeURIComponent(directorId);
  const res = await gatewayFetch(`/directors/${id}/repos`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "load that machine's repositories");
  }
  const raw = (await res.json()) as Array<Record<string, unknown>>;
  const list: RepoInfo[] = raw
    .map((r) => ({
      name: String(r.name ?? ""),
      path: String(r.path ?? ""),
      lastUsed: String(r.lastUsed ?? ""),
    }))
    .filter((r) => r.path.length > 0);
  list.sort((a, b) => b.lastUsed.localeCompare(a.lastUsed)); // newest-used first
  return list;
}

// GET /directors/{id}/known-repositories - every repository the Gateway has durably observed on the
// selected Director's machine. This is intentionally separate from getRepos: getRepos is the live
// Director registry used for the five zero-query recent choices, while this complete catalog is the
// search source and remains available when the Director tunnel is temporarily disconnected.
export async function getKnownRepositories(directorId: string, signal?: AbortSignal): Promise<RepoInfo[]> {
  const id = encodeURIComponent(directorId);
  const res = await gatewayFetch(`/directors/${id}/known-repositories`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "load that machine's repository history");
  }
  const raw = (await res.json()) as Array<Record<string, unknown>>;
  const list: RepoInfo[] = raw
    .map((repository) => ({
      name: String(repository.name ?? ""),
      path: String(repository.path ?? ""),
      lastUsed: String(repository.lastUsed ?? ""),
    }))
    .filter((repository) => repository.path.length > 0);
  list.sort((left, right) => right.lastUsed.localeCompare(left.lastUsed));
  return list;
}

// GET /directors/{id}/agents - a machine's configured, enabled agents (one per kind) for the New
// Session dialog's agent picker (issue #1497). The Director already de-duplicates by kind and orders by
// the configured order, so the list is used as-is. Entries with no type are dropped. Throws GatewayError
// on non-2xx (e.g. 502 when the Director is not connected), which the dialog surfaces inline.
export async function getAgents(directorId: string, signal?: AbortSignal): Promise<AgentChoice[]> {
  const id = encodeURIComponent(directorId);
  const res = await gatewayFetch(`/directors/${id}/agents`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "load that machine's agents");
  }
  const raw = (await res.json()) as Array<Record<string, unknown>>;
  return raw
    .map((a) => ({
      type: String(a.type ?? ""),
      displayName: String(a.displayName ?? ""),
      defaultModel: String(a.defaultModel ?? ""),
      modelLabel: String(a.modelLabel ?? ""),
    }))
    .filter((a) => a.type.length > 0);
}

// Options for createSession, mirroring the desktop New Session dialog's launch controls (issue #1497):
// pick the AGENT (the model is the agent's own configured default - there is no model override), and the
// per-session Bypass-permissions choice. No command-line arguments are composed on the client; the
// Director applies the agent's configured default launch line (its model and permission preset) exactly
// as the desktop dialog does.
export interface CreateSessionOptions {
  /** The agent kind to launch (e.g. "ClaudeCode", "Codex", "Gemini"). Defaults to "ClaudeCode". */
  agent?: string;
  /** The desktop "Bypass permission prompts" checkbox (default ON). When omitted, the Director applies
   *  its default (true). True launches the agent's configured model AND its permission-bypass flag;
   *  false launches the same model but stops for each permission prompt. */
  bypassPermissions?: boolean;
  signal?: AbortSignal;
}

// POST /directors/{id}/sessions - create a new session in repoPath. Sends the chosen agent kind and the
// Bypass-permissions choice ONLY; it never composes an args string, so the Director applies that agent's
// configured default model and permission preset - identical to the desktop New Session dialog (issue
// #1497). Returns the created SessionDto so the caller can open it. The Gateway answers 201 on success;
// throws GatewayError on non-2xx with the server's reason. Callers that pass nothing (the mobile
// NewSession flow) get Claude Code with its configured defaults, exactly as before.
export async function createSession(
  directorId: string,
  repoPath: string,
  options?: CreateSessionOptions,
): Promise<SessionDto> {
  const id = encodeURIComponent(directorId);
  const agent = options?.agent?.trim() || "ClaudeCode";
  const body: NewSessionRequest = { repoPath: repoPath.trim(), agent, wingmanEnabled: false };
  if (options?.bypassPermissions !== undefined) body.bypassPermissions = options.bypassPermissions;
  const res = await gatewayFetch(`/directors/${id}/sessions`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
    body: JSON.stringify(body),
    signal: options?.signal,
  });
  if (!res.ok) {
    let detail = `${res.status}`;
    try {
      const err = (await res.json()) as { detail?: string; error?: string };
      detail = err.detail ?? err.error ?? detail;
    } catch {
      /* non-JSON error body - keep the status code */
    }
    throw new GatewayError(res.status, `Create session failed: ${detail}`);
  }
  return (await res.json()) as SessionDto;
}

/** The applied hold state the Gateway returns from POST /sessions/{sid}/hold. */
export interface HoldResult {
  /** True when the hold has LANDED and its clock is running now (an armed snooze). */
  onHold: boolean;
  /**
   * True when the snooze was DEFERRED because the agent was working: it is accepted but has not armed
   * yet - its clock starts when the work ends (owner ruling). `onHold` is still false in this case, so a
   * caller that reads only `onHold` would wrongly conclude nothing happened; the snooze surfaces read
   * this to show a "Snoozing when it finishes" affordance instead of implying it is already held.
   */
  pending: boolean;
}

// POST /sessions/{sid}/hold - toggle the session's on-hold state. The desired state is sent
// explicitly ({ onHold }) so the call is idempotent; the Gateway returns the applied tri-state as
// { onHold, pending }. Reaches the Director through the Gateway catch-all session proxy with the
// injected Bearer.
//
// snoozeMinutes is how long to hold it. Omit it for "use my default length", which is what the plain
// Snooze click means; pass a value for a specific "Snooze for" choice. Ignored on an unsnooze - there is
// no length to un-hold for - so it is only ever sent alongside onHold=true.
//
// RETURNS BOTH FIELDS, not a bare boolean. A working session's snooze DEFERS: the Gateway answers
// { onHold: false, pending: true }, and a caller that kept only `onHold` would show no change for a
// perfectly-accepted snooze. `pending` defaults to false for an unsnooze, an immediate hold, or an old
// Gateway that predates the field.
export async function holdSession(
  sessionId: string,
  onHold: boolean,
  snoozeMinutes?: number,
  signal?: AbortSignal,
): Promise<HoldResult> {
  const sid = encodeURIComponent(sessionId);
  const body = onHold && typeof snoozeMinutes === "number" ? { onHold, snoozeMinutes } : { onHold };
  const res = await gatewayFetch(`/sessions/${sid}/hold`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
    body: JSON.stringify(body),
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "put the session on hold");
  }
  const result = (await res.json().catch(() => ({}))) as { onHold?: boolean; pending?: boolean };
  return { onHold: result.onHold ?? onHold, pending: result.pending ?? false };
}

// POST /sessions/{sid}/transcribing - mark or clear this session as transcribing a dictated
// utterance in the background (the phone hit Send in the Speak dialog and released the screen). This
// is a Gateway-owned transient flag ONLY - it is not forwarded to the Director; it drives the orange
// "Transcribing..." roster color so nobody else starts using the session while its audio is being
// uploaded and transcribed. Sent true the instant Send is pressed and false once the background
// upload/transcribe/submit finishes or fails. Reaches a Gateway-native literal route (no Director
// hop) with the injected Bearer.
export async function setTranscribing(
  sessionId: string,
  transcribing: boolean,
  signal?: AbortSignal,
): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/transcribing`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
    body: JSON.stringify({ transcribing }),
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "update the transcribing state");
  }
}

// DELETE /sessions/{sid} - kill the agent process and remove the session from the roster (the
// Android kill/remove semantics, gated behind a confirmation per the owner's #545 request). Reaches
// the Director through the Gateway catch-all session proxy with the injected Bearer.
export async function killSession(sessionId: string, signal?: AbortSignal): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}`, {
    method: "DELETE",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "close that session");
  }
}

// Dictation transcription (issue #817). Speech-to-text for the Speak dialog goes through the
// EXISTING resilient batch-upload flow the Gateway exposes for the phone (register -> chunk ->
// complete): the same record-then-ship-then-transcribe shape the native mobile app uses, resumable
// on a poor phone network because each landed chunk stays landed. The Gateway transcribes the
// reassembled clip with the hosted transcription mode the machine is set to and returns the transcript already run through
// the SAME dictionary-correction engine every surface uses - so we prefer/return that cleaned text.
//
// The Director's own /voice/utterance flow is NOT proxied through the Gateway; this /wingman/
// utterance flow is the Gateway-native equivalent and is reachable by the mobile app same-origin
// with the Bearer, so no backend change is needed.
// The optional client-measured capture-health sent with the complete call (issue #863), so the
// Gateway can persist the audio-loss deficit (recording wall-clock vs decoded audio duration) into
// the same dictation session log every other surface writes. Diagnostics only - omitting it changes
// nothing about the transcription.
export interface UtteranceCaptureHealth {
  recordedMs: number;
  decodedSeconds: number;
  sourceBytes: number;
  /** Which shell measured it ("cockpit" / "mobile"). The Gateway files the measurement under this
   *  rather than a hardcoded literal, which is what makes per-surface audio loss visible at all.
   *  Omitted by an older client; the Gateway then falls back to the tag this path always used. */
  surface?: string;
}

// The largest a single upload chunk may be. A long recording is uploaded as several chunks of at
// most this size so no single request body exceeds the Gateway limit (Kestrel's default is roughly
// thirty megabytes; a twenty-minute clip is larger). This is independent of how the server later
// splits the reassembled clip into bounded transcription requests - it only bounds the upload hop.
const MAX_UPLOAD_CHUNK_BYTES = 5_000_000;

// What a finished transcription hands back: the words, and the id of the utterance they came from.
//
// The id is what lets a surface say, at submit time, that these words were SPOKEN. The Director reads
// modality off the send source, so a transcript submitted as an ordinary prompt is recorded as typed
// unless the delivery id rides with it - which is how the same sentence came to count as spoken or
// typed depending only on which transcription path the surface used (ruling R10 of the "Clean up Your
// Throttle" mission, 2026-09-05). Callers that only want the words read `.text`.
export interface TranscribedUtterance {
  text: string;
  /** The Gateway's own id for the utterance it just transcribed. Pass to sendPrompt as
   *  spokenDeliveryId when the submitted text is the dictation and nothing else. */
  deliveryId: string;
}

export async function transcribeUtterance(
  wav: Blob,
  health?: UtteranceCaptureHealth,
  signal?: AbortSignal,
  onProgress?: (uploadedChunks: number, totalChunks: number) => void,
): Promise<TranscribedUtterance> {
  // 1. Register the upload (mints an id the chunk + complete calls address).
  const reg = await gatewayFetch(`/wingman/utterance/upload`, {
    method: "POST",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!reg.ok) {
    const error = await readGatewayErrorBody(reg);
    throw new GatewayError(reg.status, transcriptionFailureMessage(error, reg.status));
  }
  const regBody = (await reg.json()) as { upload_id?: string };
  const uploadId = regBody.upload_id;
  if (!uploadId) {
    throw new GatewayError(reg.status, "transcription register returned no upload id");
  }

  // 2. Upload the WAV in bounded chunks so a long recording never exceeds the Gateway request-body
  //    limit. Each chunk carries its own SHA256, so the server rejects corruption and treats a
  //    retried chunk as a free no-op; the server reassembles the chunks in order before transcribing.
  const bytes = new Uint8Array(await wav.arrayBuffer());
  const id = encodeURIComponent(uploadId);
  const ranges = planUploadChunks(bytes.length, MAX_UPLOAD_CHUNK_BYTES);
  onProgress?.(0, ranges.length);
  for (const range of ranges) {
    const part = bytes.subarray(range.start, range.end);
    const sha = await sha256Hex(part);
    const put = await gatewayFetch(`/wingman/utterance/${id}/chunk/${range.index}`, {
      method: "PUT",
      headers: { "Content-Type": "application/octet-stream", "X-Chunk-Sha256": sha, ...authHeaders() },
      body: part,
      signal,
    });
    if (!put.ok) {
      const error = await readGatewayErrorBody(put);
      throw new GatewayError(put.status, transcriptionFailureMessage(error, put.status));
    }
    onProgress?.(range.index + 1, ranges.length);
  }

  // 3. Complete with the real chunk count -> the server reassembles all chunks, transcribes the clip
  //    (the pipeline itself splits the reassembled audio into bounded transcription requests), applies
  //    the dictionary correction, and returns the cleaned transcript.
  const comp = await gatewayFetch(`/wingman/utterance/${id}/complete`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
    body: JSON.stringify({
      totalChunks: ranges.length,
      mime: "audio/wav",
      ext: "wav",
      clientRecordedMs: health?.recordedMs,
      clientDecodedSeconds: health?.decodedSeconds,
      clientSourceBytes: health?.sourceBytes,
      clientSurface: health?.surface,
    }),
    signal,
  });
  const compBody = (await comp.json().catch(() => ({}))) as { transcript?: string; error?: string };
  if (!comp.ok) {
    // Out of credits / cap (issue #942): a typed CreditsError carrying the shared message + call-to-action.
    if (comp.status === 402) throw creditsErrorFrom(compBody);
    throw new GatewayError(comp.status, transcriptionFailureMessage(compBody.error, comp.status));
  }
  return { text: (compBody.transcript ?? "").trim(), deliveryId: uploadId };
}

// Hex SHA256 of the upload bytes via the Web Crypto API (available in any secure context, which a
// microphone-capable page already is).
async function sha256Hex(bytes: Uint8Array): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

// ===== Durable, server-owned dictation upload (issue #1006, strengthened for #1182) ==============
// Streams the raw recorded audio (already saved to the on-device durable store) to the Gateway in
// resumable, SHA-checked chunks; the Gateway then assembles, transcribes, and INJECTS the turn into
// the session itself. Once the server confirms it owns the turn, the local copy is deleted.
//
// This function is ONE self-contained delivery attempt. The retry CADENCE (hard for the first hour,
// then throttled, resumed on connectivity) lives in the background driver (dictation/backgroundSend.ts),
// which calls this repeatedly with the same uploadId. Because that uploadId is also the server's
// Idempotency-Key, every attempt is safe:
//   - Register is idempotent and RE-CREATES the staging folder even after the server's abandoned-upload
//     sweep, so a resume after an hour re-drives from the on-device copy (never a loss, criterion 9).
//   - The client discovers exactly which chunks the server still needs from complete's 409 { missing }
//     response, and uploads only those - a resume continues from the next missing chunk, never a restart
//     from zero (criterion 3).
//   - A dropped connection mid-chunk PAUSES the attempt (returns a held, retryable outcome); it does not
//     fail the whole clip. The next attempt resumes from the still-missing chunks.
//   - A complete that already succeeded server-side but whose response was lost is retried against the
//     Gateway's per-uploadId idempotency cache, which returns the SAME submitted outcome - so the turn is
//     injected exactly once and the #1135 duplicate pile-up cannot return (criterion 7).

/** The tight allow-list of GENUINELY PERMANENT, non-retryable transcription failures (issue #1184). A clip
 *  that hits one of these can never succeed AS-SENT, so it must stop the auto-retry loop and PARK rather
 *  than re-drive forever. EVERYTHING outside this list (network, provider 502/504, busy session, out of
 *  credits) stays retryable/held. Default is retryable; only these reasons are permanent.
 *   - "audio-too-large": the clip is over the provider's per-request byte cap and cannot be split as-sent.
 *   - "unsupported-format": the audio is a format the Gateway cannot decode or split.
 *   - "empty-recording": the on-device copy was read SUCCESSFULLY and contained ZERO BYTES, so there is no
 *     audio to send. Decided entirely on the device, before any network work - see the empty-audio guard in
 *     uploadDictationToSession. Permanent because the bytes are the input: re-reading the same empty copy
 *     produces the same nothing however often it is asked. A read that THROWS is deliberately NOT this - it
 *     says nothing about the length, so it stays held and retryable
 *     (DICTATION_HELD_UNREADABLE_MESSAGE). Do not widen this reason to cover it: parking a recording that a
 *     later read would have recovered strands it, and tells the user it was empty when it was not. */
export type PermanentDictationReason = "audio-too-large" | "unsupported-format" | "empty-recording";

/** Outcome of one dictation delivery attempt.
 *  - `terminal` true: the server made a final decision (injected the turn, or deliberately dropped it as
 *    stale / empty) and the durable local copy can be deleted.
 *  - `permanent` true: a genuinely permanent, non-retryable failure (an allow-listed `permanentReason`,
 *    issue #1184). NOT terminal - the on-device copy is KEPT and the clip is PARKED (the auto-loop stops)
 *    until the user explicitly retries it; nothing was injected.
 *  - otherwise (`terminal` false, `permanent` falsey): nothing final happened; the copy is KEPT and the
 *    driver retries. `error` carries the honest "held, will keep trying" reason and `outOfCredits` flags
 *    any money-shaped 402 (credits, subscription, fair use, unknown) so the driver throttles its retry
 *    loop - a fast retry fixes none of them. The app-level notice and the held copy both come from the
 *    Gateway's MAPPED state (issue #1360), never from a hardcoded credits sentence. */
export interface DictationSubmitResult {
  terminal: boolean;
  submitted: boolean;
  movedOn: boolean;
  /** True when the server returned an ABANDONED upload id (the dictation was given up server-side, issue
   *  #1183): terminal like a delivered turn, so the driver drops the on-device copy and does not re-drive,
   *  but nothing was injected. */
  abandoned?: boolean;
  /** True when the failure is genuinely permanent and non-retryable (issue #1184): the driver parks the
   *  clip (keeps the audio, stops the auto-loop) and offers an explicit user Retry. */
  permanent?: boolean;
  /** The allow-listed reason a permanent failure was parked (only set when `permanent` is true). */
  permanentReason?: PermanentDictationReason;
  transcript: string;
  error?: string;
  outOfCredits?: boolean;
}

export interface DictationUploadArgs {
  sessionId: string;
  /** Client-generated id (the durable record id); also the server upload id and Idempotency-Key. */
  uploadId: string;
  /** Raw recorded audio exactly as the microphone produced it. */
  audio: Blob;
  before: string;
  after: string;
  prefix: string;
  /** The session's TotalBufferBytes when the clip was recorded, for the server's moved-on guard.
   *  Omitted when genuinely unknown - JSON.stringify drops the key, and the server's absent-field
   *  default skips the guard for this clip. Never a fabricated zero: zero is a real reading (a
   *  terminal that had produced nothing yet), and unknown must stay distinguishable from it
   *  (issue #2478). */
  baselineBufferBytes?: number;
  resumed: boolean;
  /** Capture-health (issue #863), optional: the recording wall-clock, the decoded audio duration, and
   *  the source blob size, measured once at Send time. Forwarded on the complete call so the Gateway
   *  persists the audio-loss deficit for the fire-and-forget Send path (which never transcodes
   *  on-device). Omitted when the on-device decode failed - diagnostics only, never blocks delivery. */
  clientRecordedMs?: number;
  clientDecodedSeconds?: number;
  clientSourceBytes?: number;
  /** Which shell recorded the clip ("cockpit-send" / "mobile-send"). The Gateway files the
   *  capture-health measurement under this instead of a hardcoded literal, so per-surface audio loss
   *  can actually be told apart in the log. Omitted by an older client; the Gateway then falls back. */
  clientSurface?: string;
}

/** The honest, plain-English line for a dictation whose delivery is paused because the connection
 *  dropped (mid-upload, or the Gateway is unreachable). The audio is safe on the device and the
 *  background driver keeps trying - never "was not transcribed", because it is held, not lost. */
export const DICTATION_HELD_NO_CONNECTION_MESSAGE =
  "No connection - your recording is saved and will keep trying.";

/** The held line for a recording whose saved copy could not be READ on this attempt - the read threw rather
 *  than coming back empty. Held, deliberately: a read can fail under browser storage or memory pressure and
 *  succeed on the next attempt, so this must never claim the recording is empty or gone. A read that comes
 *  back zero-length IS permanent and takes the parked "empty-recording" path instead; only the throw lands
 *  here, because a throw tells us nothing about how long the recording is. */
export const DICTATION_HELD_UNREADABLE_MESSAGE =
  "Couldn't read the saved recording just now - it is still on your device and delivery will keep trying.";

/** The held line when transcription credits ran out: kept, and it sends once credits are available.
 *  This wording is reachable ONLY from the direct-API `insufficient_credits` state (the Gateway maps
 *  that 402 code to state "NeedsCredits") - see dictationHeld402Message. */
export const DICTATION_HELD_CREDITS_MESSAGE =
  "Out of transcription credits - your recording is saved and will send when credits are added.";

/** The held line for a 402 whose mapped state is NOT the credits one: the Gateway's own mapped copy
 *  (subscription required, fair-use limit, or the neutral unknown-code sentence), followed by the
 *  honest saved-on-device clause. The Gateway owns the verdict and its wording (rule 7 - the client is
 *  dumb); this client must never replace a subscription/fair-use/unknown refusal with credits wording
 *  the owner ruled a normal member never sees (issue #1360). */
export function dictationHeld402Message(info: HostedAiUnavailable): string {
  if (info.state === "NeedsCredits") return DICTATION_HELD_CREDITS_MESSAGE;
  const text = info.text.trim().replace(/\.$/, "");
  return `${text}. Your recording is saved on this device.`;
}

export async function uploadDictationToSession(
  args: DictationUploadArgs,
  signal?: AbortSignal,
): Promise<DictationSubmitResult> {
  // Live status is published for the mechanical steps (uploading / transcribing / done) here; the
  // driver owns the held-and-retrying status between attempts. A non-terminal outcome returns a held
  // result (terminal:false) with the honest reason, so the driver keeps the audio and retries.
  const sid = args.sessionId;
  const uploadId = args.uploadId;
  const held = (error: string, outOfCredits = false): DictationSubmitResult =>
    ({ terminal: false, submitted: false, movedOn: false, transcript: "", error, outOfCredits });
  const permanent = (reason: PermanentDictationReason): DictationSubmitResult =>
    ({ terminal: false, submitted: false, movedOn: false, transcript: "", permanent: true, permanentReason: reason });

  // 1. Register (idempotent by Idempotency-Key: re-opens the same staging on a resume, and RE-CREATES it
  //    if the server already swept the abandoned upload - so we always re-drive from the on-device copy).
  publishDictationStatus({ sessionId: sid, uploadId, phase: "uploading", uploaded: 0, total: 1 });
  let reg: Response;
  try {
    reg = await gatewayFetch(`/dictation/upload`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json", "Idempotency-Key": args.uploadId, ...authHeaders() },
      body: JSON.stringify({ sessionId: args.sessionId, baselineBufferBytes: args.baselineBufferBytes }),
      signal,
    });
  } catch {
    return held(DICTATION_HELD_NO_CONNECTION_MESSAGE);
  }
  if (!reg.ok) return held(transcriptionFailureMessage(await readGatewayErrorBody(reg), reg.status, true));
  const regBody = (await reg.json().catch(() => ({}))) as {
    upload_id?: string;
    terminal?: boolean;
    submitted?: boolean;
    movedOn?: boolean;
    dropped?: boolean;
    transcript?: string;
  };
  const id = encodeURIComponent(regBody.upload_id ?? args.uploadId);

  // Durable de-dupe at register (issue #1183): the server already reached a terminal outcome for this
  // upload id (delivered or abandoned) - our earlier response was lost. Treat it exactly like a fresh
  // terminal outcome: acknowledge it (so the server can retire the tombstone) and return terminal so the
  // driver drops the on-device copy. No chunks are re-uploaded and nothing is injected a second time.
  if (regBody.terminal === true) {
    await ackDictation(id);
    return {
      terminal: true,
      submitted: Boolean(regBody.submitted),
      movedOn: Boolean(regBody.movedOn),
      abandoned: Boolean(regBody.dropped),
      transcript: regBody.transcript ?? "",
    };
  }

  // 2. Read the whole clip from the (already durable) on-device copy and plan its bounded chunks.
  //
  // THE EMPTY-AUDIO GUARD. planUploadChunks documents that "a zero-length payload yields no ranges (the
  // caller guards empty audio upstream)" - and until this guard existed, THIS caller did not. A clip whose
  // on-device copy read back as zero bytes therefore planned NO chunks, uploaded nothing, and sent the
  // server totalChunks:0, which the complete endpoint correctly refuses with a 400. A 400 is not one of the
  // allow-listed permanent reasons, so it fell through to the retryable/held arm and the clip re-drove
  // forever: the phone showed "Saved - still sending" for a recording that could never be sent, and the
  // Gateway collected a staging directory holding a delivery record and no audio. That residue is how this
  // was found - three of them registered in one second, none with a single byte behind it.
  //
  // ZERO LENGTH AND A FAILED READ ARE NOT THE SAME THING, and collapsing them is a defect of its own.
  //   - A read that SUCCEEDS and yields zero bytes is permanent: the bytes are the input, and re-reading
  //     the same empty copy produces the same nothing however many times it is asked.
  //   - A read that THROWS says nothing about the length. A perfectly good recording can fail to read under
  //     browser storage or memory pressure and read fine on the next attempt, so parking it would strand a
  //     recording that automatic delivery would have recovered - and would tell the user "there was nothing
  //     to send" about audio that is still there. That claim would be false, which is the same sin as the
  //     "Saved - still sending" it replaced, only in the other direction.
  // So a throw stays HELD and keeps retrying, with a reason that says what actually happened.
  let bytes: Uint8Array;
  try {
    bytes = new Uint8Array(await args.audio.arrayBuffer());
  } catch {
    return held(DICTATION_HELD_UNREADABLE_MESSAGE);
  }
  if (bytes.length === 0) return permanent("empty-recording");

  const ranges = planUploadChunks(bytes.length, MAX_UPLOAD_CHUNK_BYTES);
  const total = ranges.length;
  const completeBody = {
    sessionId: args.sessionId,
    totalChunks: total,
    mime: args.audio.type || "audio/webm",
    ext: extForMime(args.audio.type),
    before: args.before,
    after: args.after,
    prefix: args.prefix,
    baselineBufferBytes: args.baselineBufferBytes,
    resumed: args.resumed,
    // Capture-health (issue #863): forwarded so the Gateway persists this path's audio-loss deficit
    // into the same dictation session log every other surface writes. Undefined fields are omitted.
    clientRecordedMs: args.clientRecordedMs,
    clientDecodedSeconds: args.clientDecodedSeconds,
    clientSourceBytes: args.clientSourceBytes,
    clientSurface: args.clientSurface,
  };
  const complete = (): Promise<Response> =>
    gatewayFetch(`/dictation/${id}/complete`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
      body: JSON.stringify(completeBody),
      signal,
    });

  publishDictationStatus({ sessionId: sid, uploadId, phase: "uploading", uploaded: 0, total });

  // 3. Resume-from-missing loop. complete tells us (cheaply, before any transcription) which chunks the
  //    server still needs (409 { missing }); we upload exactly those from the on-device copy and complete
  //    again. On the first ever attempt nothing is up yet, so the first complete reports every index and
  //    we upload the whole clip; on a resume only the still-missing set is sent. Bounded so a server that
  //    keeps reporting the same chunk missing cannot spin forever - it becomes a held retry instead.
  let uploadedAllThisAttempt = false;
  const maxRounds = total + 2;
  for (let round = 0; round < maxRounds; round++) {
    // Only the complete AFTER all chunks are up does the real transcribe; show "transcribing" then.
    if (uploadedAllThisAttempt) publishDictationStatus({ sessionId: sid, uploadId, phase: "transcribing" });
    let comp: Response;
    try {
      comp = await complete();
    } catch {
      return held(DICTATION_HELD_NO_CONNECTION_MESSAGE);
    }

    if (comp.status === 409) {
      const body = (await comp.json().catch(() => ({}))) as { missing?: number[]; record?: string; error?: string };
      // The Gateway refused to touch this upload's DELIVERY RECORD (issue #2745): the record on the server is
      // there but is not readable as a delivery record, or belongs to another account. That is not a
      // missing-chunk answer, and re-sending chunks cannot change it - an operator has to look at the file
      // the server named. Held with that message; no ack, because an ack retires the server's evidence.
      if (typeof body.record === "string") return held(transcriptionFailureMessage(body.error, comp.status, true));
      // Missing chunks: send exactly those, pausing (held) if the connection drops mid-chunk.
      const missing = (body.missing ?? []).filter((i) => ranges[i]);
      if (missing.length === 0) return held(transcriptionFailureMessage(undefined, 502, true));
      let uploaded = total - missing.length;
      publishDictationStatus({ sessionId: sid, uploadId, phase: "uploading", uploaded, total });
      for (const i of missing) {
        const r = ranges[i];
        const part = bytes.subarray(r.start, r.end);
        const sha = await sha256Hex(part);
        let put: Response;
        try {
          put = await gatewayFetch(`/dictation/${id}/chunk/${r.index}`, {
            method: "PUT",
            headers: { "Content-Type": "application/octet-stream", "X-Chunk-Sha256": sha, ...authHeaders() },
            body: part,
            signal,
          });
        } catch {
          // Connection dropped mid-chunk: pause here, keep every chunk that already landed, and let the
          // driver resume from the next missing chunk on the following attempt (criterion 3).
          return held(DICTATION_HELD_NO_CONNECTION_MESSAGE);
        }
        if (put.status === 404) {
          // The server swept this upload's staging between our register and this chunk. Re-register on the
          // next attempt (same Idempotency-Key) and re-drive from the on-device copy (criterion 9).
          return held(DICTATION_HELD_NO_CONNECTION_MESSAGE);
        }
        if (!put.ok) return held(transcriptionFailureMessage(await readGatewayErrorBody(put), put.status, true));
        uploaded += 1;
        publishDictationStatus({ sessionId: sid, uploadId, phase: "uploading", uploaded, total });
      }
      uploadedAllThisAttempt = true;
      continue;
    }

    if (comp.status === 402) {
      // A money-shaped refusal. The body carries the Gateway's MAPPED state and copy (issue #1360):
      // creditsErrorFrom parses it and fires the app-level notice, and the held strip renders the SAME
      // mapped copy - the credits wording only for the direct-API insufficient_credits state, never for
      // a subscription/fair-use/unknown refusal. The audio stays held either way; a plain fast retry
      // will not fix any of these, so the driver throttles this.
      const err = creditsErrorFrom(await comp.json().catch(() => ({})));
      return held(dictationHeld402Message(err.info), true);
    }

    const body = (await comp.json().catch(() => ({}))) as {
      submitted?: boolean; movedOn?: boolean; dropped?: boolean; transcript?: string; error?: string;
      permanent?: boolean; reason?: string;
    };

    // Genuinely permanent, non-retryable failure (issue #1184). The server (a later, coordinated step)
    // signals this on complete with { permanent: true, reason: <allow-listed> } - naturally an HTTP 422,
    // but we key off the typed body flag, not the status, so the server may pick any status. Only the
    // tight allow-list parks; a permanent flag with any other reason falls through to the retryable/held
    // path below, so the default stays retryable and the auto-loop is only ever stopped for the two
    // reasons that truly can never succeed as-sent.
    const reason = permanentReasonFrom(body.permanent, body.reason);
    if (reason !== null) return permanent(reason);

    if (!comp.ok) {
      // A reachable Gateway that answered with a server-side transcription fault (timeout / outage / no
      // key / session gone). Held, not lost - the honest "saved and will keep trying" copy.
      return held(transcriptionFailureMessage(body.error, comp.status, true));
    }

    // 200: the server made a final decision. submitted -> the turn was injected; movedOn -> the server
    // deliberately dropped a stale resumed clip; dropped -> the upload id was abandoned server-side (issue
    // #1183); neither -> a silent/empty clip with nothing to submit. All are terminal: the server owns the
    // outcome and holds a durable delivery record. Acknowledge it so the server can retire that tombstone
    // (best-effort, idempotent), then return terminal so the driver drops the durable local copy. The
    // background driver owns the terminal status (a "done" for a delivered turn, or a quiet clear).
    await ackDictation(id);
    return {
      terminal: true,
      submitted: Boolean(body.submitted),
      movedOn: Boolean(body.movedOn),
      abandoned: Boolean(body.dropped),
      transcript: body.transcript ?? "",
    };
  }

  // The server kept reporting missing chunks past the bounded rounds (a chunk that will not stick, e.g. a
  // persistent SHA rejection). Hold it - the driver retries from a clean register on the next attempt.
  return held(DICTATION_HELD_NO_CONNECTION_MESSAGE);
}

// Map a complete response's permanent-failure signal to an allow-listed reason, or null when it is not a
// permanent failure we recognize (issue #1184). Only "audio-too-large" and "unsupported-format" park; any
// other value - including a permanent flag with an unknown/blank reason - returns null so the clip stays
// on the default retryable/held path. This is the SINGLE gate that decides "park" versus "keep retrying",
// so the allow-list can never widen by accident.
function permanentReasonFrom(permanent: boolean | undefined, reason: string | undefined): PermanentDictationReason | null {
  if (permanent !== true) return null;
  if (reason === "audio-too-large" || reason === "unsupported-format") return reason;
  return null;
}

// Acknowledge a terminal dictation outcome so the Gateway can retire its durable de-dupe tombstone (issue
// #1183). Best-effort and idempotent, keyed by the (already-encoded) upload id: a lost ack simply leaves
// the tiny tombstone in place and a later re-complete returns the same outcome and re-acks. Never throws -
// a failed ack must never turn a delivered turn into an error.
async function ackDictation(encodedUploadId: string): Promise<void> {
  try {
    await gatewayFetch(`/dictation/${encodedUploadId}/ack`, {
      method: "POST",
      headers: { Accept: "application/json", ...authHeaders() },
    });
  } catch {
    /* best-effort: the tombstone persists and a later re-complete re-acks */
  }
}

// POST /dictation/{uploadId}/abandon (issue #1181, Task 5): the user gave up on this dictation. Tells the
// Gateway to mark the durable upload ABANDONED - discarding the staged audio and clearing the session lock.
// Unlike the fire-and-forget ack, this RETURNS whether the Gateway actually confirmed: the caller must know,
// because if the marker is not cleared the session would stay locked/orange forever. Returns false when the
// call could not reach a healthy Gateway, so the caller keeps the abandoning record and retries.
export async function abandonDictation(uploadId: string): Promise<boolean> {
  try {
    const res = await gatewayFetch(`/dictation/${encodeURIComponent(uploadId)}/abandon`, {
      method: "POST",
      headers: { Accept: "application/json", ...authHeaders() },
    });
    return res.ok;
  } catch {
    return false;
  }
}

// Turn a raw dictation-complete failure (any non-OK response from POST /dictation/{id}/complete) into a
// short, honest, plain-English sentence for the status strip and the error banner.
//
// This is the SINGLE place a dictation failure is turned into user-facing words. It never surfaces the
// raw server JSON/text at the user (the bug this fixes: a server-side outage used to reach the user as a
// raw "Transcription returned 502: {...}" dump), and every known server-side condition gets its own
// specific line so the user is told WHAT went wrong - a transcription-service outage, a busy session, no
// method configured - not merely that "transcription failed" (issue #1139 follow-up).
//
// `durable` frames the message for the caller's recovery model (issue #1182). The durable dictation path
// (uploadDictationToSession) keeps the audio and keeps retrying, so it passes durable=true and the copy
// says "saved and will keep trying" - never "was not transcribed", because it is held, not lost. The
// synchronous voice-narration path (transcribeUtterance) has no durable copy, so it uses the default
// (durable=false) and reports the fault plainly.
export function transcriptionFailureMessage(serverError: string | undefined, status: number, durable = false): string {
  const raw = (serverError ?? "").toLowerCase();

  if (status === 401)
    return "This device is no longer authorized. Please sign in again.";

  if (status === 403)
    return "This device is not allowed to use transcription on this Gateway.";

  // The Gateway refused to re-open, deliver, or write over this upload because its on-disk DELIVERY RECORD
  // is there but cannot be read (issue #2745). "Unreadable" (a 423) means it could not be read just now
  // (locked, a disk fault) and a retry may read it; anything else (a 409) means it was read and is not a
  // delivery record, or is another account's, and no retry will change that - an operator has to look at
  // the file the server named in its log. Neither is a transcription outage, and the saved copy must never
  // be sent again on the strength of either, so this is ahead of every "transcription service" line below.
  // Keyed on the sentence, not the status, so the wording follows what the server SAID was wrong.
  if (raw.includes("delivery record for upload"))
    return raw.includes(" is unreadable")
      ? "The server could not read this recording's delivery record just now. Your recording is saved and will try again."
      : "The server's delivery record for this recording is damaged and needs an operator to look at it. Your recording is saved and cannot go through until that is fixed.";

  // The session the dictation was headed for is gone (exited / not found).
  if (status === 404 || status === 410 || raw.includes("session not found") || raw.includes("session has exited"))
    return "That session is no longer available, so your dictation couldn't be delivered.";

  // No transcription method is configured on the Gateway (no key for the selected mode). A plain retry
  // will not fix it, so point at Settings rather than promising a quick retry.
  if (raw.includes("no key configured") || raw.includes("no key set"))
    return durable
      ? "No transcription method is set up. Open Settings > Transcription; your recording is saved and will send once one is chosen."
      : "No transcription method is set up. Open Settings > Transcription and choose one.";

  // The upstream speech-to-text provider took too long to respond.
  if (status === 504 || raw.includes("upstream_timeout") || raw.includes("timed out") || raw.includes("did not respond"))
    return durable
      ? "The transcription service timed out - your recording is saved and will keep trying."
      : "The transcription service timed out. Dictation was not transcribed.";

  // The upstream speech-to-text provider is down / circuit-broken ("temporarily unavailable after
  // repeated failures"). The Gateway wraps the proxy's 503/504 as a 502 whose body carries this code.
  if (status === 503 || raw.includes("upstream_unavailable") || raw.includes("temporarily unavailable"))
    return durable
      ? "The transcription service is temporarily unavailable - your recording is saved and will keep trying."
      : "The transcription service is temporarily unavailable. Dictation was not transcribed.";

  // The transcript was produced but could not be delivered into the session (parked on a prompt or a
  // permission dialog and refusing typed input).
  if (raw.includes("submit to session failed"))
    return durable
      ? "Couldn't deliver your dictation to the session yet - it may be busy or waiting on a prompt. It's saved and will keep trying."
      : "Couldn't deliver your dictation to the session - it may be busy or waiting on a prompt.";

  // Any other server-side transcription fault - the provider itself returned an error ("openai
  // transcription failed" / upstream_error), an empty assembly, some other 5xx. A real backend problem,
  // not the user's audio: say so plainly instead of dumping the raw server response.
  return durable
    ? "The transcription service had a problem - your recording is saved and will keep trying."
    : "The transcription service had a problem and couldn't process your recording. Dictation was not transcribed.";
}

function extForMime(mime: string | undefined): string {
  const m = (mime ?? "").toLowerCase();
  if (m.includes("webm")) return "webm";
  if (m.includes("ogg")) return "ogg";
  if (m.includes("mp4") || m.includes("m4a") || m.includes("aac")) return "m4a";
  if (m.includes("mpeg") || m.includes("mp3")) return "mp3";
  if (m.includes("wav")) return "wav";
  return "webm";
}

// ===== Wingman Voice mode (issue #850): the mobile hands-free narration loop =====
// The whole backend is already built and proven on the desktop Cockpit voice tab and the native
// phone app (the explain/voice/ready/menu endpoints below). These typed helpers are the mobile
// PWA's same-origin door to them, each carrying the same Bearer the rest of the client uses so the
// Voice screen works with global Gateway auth on or off. The Wingman is READ-ONLY: explain and the
// voice reads never type into the session; only menu-press / sendPrompt reach the agent, through
// the existing single write chokepoint.
//
// These response shapes are returned by the Gateway via Results.Json WITHOUT a [Produces]
// annotation, so they are not in the generated OpenAPI schema; they are read with narrow local
// types for exactly the fields the Voice screen consumes (the same pattern getDirectors uses).

/** Read-only narration of the latest turn (POST /sessions/{sid}/wingman/explain). Also MARKS the
 *  session as a voice session, so the Gateway's turn-end watcher re-narrates every following turn. */
export interface WingmanExplain {
  reply: string;
  spoken: string;
  replySeconds: number;
  /** True for a fresh/text-only session with nothing to summarize yet (no audio was produced). */
  nothingYet: boolean;
}

/** The precomputed spoken summary + readiness metadata for a session (GET .../wingman/voice). */
export interface WingmanVoice {
  ready: boolean;
  spoken: string;
  reply: string;
  /** ISO-8601 stamp of when this clip was generated; it is the clip's identity (a new turn -> a
   *  new stamp), so the phone uses it to tell a fresh narration from the one it already holds. */
  generatedAt: string;
}

/** One option of a waiting on-screen choice (GET .../wingman/menu). */
export interface WingmanMenuOption {
  /** Short human label, e.g. "1. Yes". */
  key: string;
  /** The exact keystrokes that pick this option. For a single-select menu this includes the
   *  confirm (e.g. "1\r"); for a multiple-select checklist it is just the toggle (e.g. "1"). */
  send: string;
  /** The consequence/risk of choosing this option (<= 18 words). */
  note: string;
  /** True on at most one option - the Wingman's recommended/default pick. */
  recommended: boolean;
}

/** A detected waiting choice and its options (GET .../wingman/menu). */
export interface WingmanMenu {
  isMenu: boolean;
  question: string;
  spoken: string;
  /** "single" to pick exactly one; "multiple" for a pick-any checklist completed by submit. */
  selectionMode: "single" | "multiple";
  /** The keystroke that completes a multiple-select menu (e.g. "\r"); empty for single-select. */
  submit: string;
  options: WingmanMenuOption[];
}

// POST /sessions/{sid}/wingman/explain - mark the session as a voice session AND read its latest
// turn back as a spoken summary, without sending anything into the session. This is what entering
// voice mode fires; the Gateway caches the spoken text + audio so the phone can then download it.
export async function markVoiceAndExplain(sessionId: string, signal?: AbortSignal): Promise<WingmanExplain> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/wingman/explain`, {
    method: "POST",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    // Switching a session to voice mode ran into out-of-credits (issue #942): the shared notice.
    if (res.status === 402) throw creditsErrorFrom(await res.json().catch(() => ({})));
    throw await GatewayError.from(res, "ask the wingman to explain");
  }
  const body = (await res.json()) as Partial<WingmanExplain>;
  return {
    reply: body.reply ?? "",
    spoken: body.spoken ?? "",
    replySeconds: Number(body.replySeconds ?? 0),
    nothingYet: Boolean(body.nothingYet),
  };
}

// GET /sessions/{sid}/wingman/voice - the precomputed spoken summary + readiness for the session's
// current (latest) narration. ready=false means the Gateway has nothing cached yet.
export async function getWingmanVoice(sessionId: string, signal?: AbortSignal): Promise<WingmanVoice> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/wingman/voice`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "load the wingman voice state");
  }
  const body = (await res.json()) as Partial<WingmanVoice>;
  return {
    ready: Boolean(body.ready),
    spoken: body.spoken ?? "",
    reply: body.reply ?? "",
    generatedAt: body.generatedAt ?? "",
  };
}

// GET /sessions/{sid}/wingman/voice/audio - the cached MP3 bytes for the session's current clip.
// Returned as an ArrayBuffer so the phone-side download gate (voice/clips.ts) can store it locally
// and expose a "phone-ready" state distinct from "gateway-ready". Binary, never base64 over the wire.
export async function fetchWingmanVoiceAudio(sessionId: string, signal?: AbortSignal): Promise<ArrayBuffer> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/wingman/voice/audio`, {
    method: "GET",
    headers: { Accept: "audio/mpeg", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    // Narration audio unavailable because of credits (issue #942): a 402 body is JSON even here.
    if (res.status === 402) throw creditsErrorFrom(await res.json().catch(() => ({})));
    throw await GatewayError.from(res, "load the wingman audio");
  }
  return res.arrayBuffer();
}

// GET /sessions/{sid}/wingman/menu - is the agent showing an on-screen menu right now, and what are
// its options? The Voice screen reads this to render pressable option buttons. The Gateway returns
// isMenu=false cheaply (no model call) when the terminal does not look like a menu.
export async function getWingmanMenu(sessionId: string, signal?: AbortSignal): Promise<WingmanMenu> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/wingman/menu`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "load the wingman menu");
  }
  const body = (await res.json()) as Partial<WingmanMenu> & { options?: Partial<WingmanMenuOption>[] };
  return {
    isMenu: Boolean(body.isMenu),
    question: body.question ?? "",
    spoken: body.spoken ?? "",
    selectionMode: body.selectionMode === "multiple" ? "multiple" : "single",
    submit: body.submit ?? "",
    options: (body.options ?? []).map((o) => ({
      key: o.key ?? "",
      send: o.send ?? "",
      note: o.note ?? "",
      recommended: Boolean(o.recommended),
    })),
  };
}

// POST /sessions/{sid}/wingman/menu-press - answer a waiting choice from the phone by sending the
// exact keystrokes. This is the single write chokepoint for a choice (the Wingman charter stays
// read-only). For a single-select menu, `send` is one option's full keystroke and `submit` is
// omitted; for a multiple-select checklist, `send` is the concatenated toggle keystrokes of every
// chosen option and `submit` completes the selection.
export async function pressWingmanMenu(
  sessionId: string,
  send: string,
  submit?: string,
  signal?: AbortSignal,
): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const body: { send: string; submit?: string } = submit ? { send, submit } : { send };
  const res = await gatewayFetch(`/sessions/${sid}/wingman/menu-press`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
    body: JSON.stringify(body),
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "press that wingman menu item");
  }
}

// POST /sessions/{sid}/voice-mode { enabled } - the owning Director's authoritative voice flag. This
// is the SAME endpoint the native phone app drives (DirectorVoiceClient.SetVoiceModeAsync): enabled
// sets the session's mobile view mode to Voice, so SessionDto.VoiceMode flips true for every client
// (the roster shows it as a voice session and it persists across navigation); disabled leaves voice
// (view mode -> Text). It reaches the Director through the Gateway catch-all session proxy with the
// injected Bearer, exactly like sendPrompt/holdSession. Switching voice on calls this AND
// markVoiceAndExplain (which marks the Gateway's turn-end re-narration set and reads the first turn).
export async function setVoiceMode(sessionId: string, enabled: boolean, signal?: AbortSignal): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/voice-mode`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
    body: JSON.stringify({ enabled }),
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "change voice mode");
  }
}

// POST /sessions/{sid}/wingman/voice/stop - tell the Gateway to stop keeping voice for this session
// (issue #859). It unmarks the session as a voice session, so the Gateway stops spending the
// per-turn Opus translation + text-to-speech on it (the turn-end watcher and the background sweep
// both skip it once unmarked) and drops its cached clip. The counterpart to markVoiceAndExplain
// (which marks it on entry). "Turn voice off" calls this together with setVoiceMode(sid, false): the
// Director call flips the roster flag, this call stops the Gateway work. Gateway-side and read-only -
// it sends nothing into the session.
export async function stopWingmanVoice(sessionId: string, signal?: AbortSignal): Promise<void> {
  const sid = encodeURIComponent(sessionId);
  const res = await gatewayFetch(`/sessions/${sid}/wingman/voice/stop`, {
    method: "POST",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) {
    throw await GatewayError.from(res, "stop the wingman voice");
  }
}

// The per-session outcome the fleet-wide voice-mode call reports back (issue #1765). `ok` sessions were
// switched; a not-ok session was skipped (its owning computer was not reachable) and `reason` says so
// in plain English.
export interface VoiceModeAllSessionResult {
  sessionId: string;
  name: string | null;
  ok: boolean;
  reason: string | null;
}

// The whole-fleet result: what was asked for (enabled), how many sessions the Gateway saw, how many it
// actually switched, how many it skipped, and the per-session detail.
export interface VoiceModeAllResult {
  enabled: boolean;
  total: number;
  changed: number;
  skipped: number;
  sessions: VoiceModeAllSessionResult[];
}

// GET /sessions/voice-mode/all - IS THIS FLEET IN VOICE MODE? The one place to ask.
//
// A client must never answer this for itself. The obvious local guess - "does any session have voiceMode
// set?" - is a DIFFERENT question: it turns true the instant one session is on and stays true while nine
// others are off. Clients guessing it that way is exactly why the fleet switch offered only "turn it all
// off" forever, so a session created later could never be switched on, and why nothing on screen could
// honestly say which state you were in. The Gateway holds the intent; this reads it.
export async function getVoiceModeAllSessions(signal?: AbortSignal): Promise<boolean> {
  const res = await gatewayFetch(`/sessions/voice-mode/all`, {
    method: "GET",
    headers: { Accept: "application/json", ...authHeaders() },
    signal,
  });
  if (!res.ok) throw await GatewayError.from(res, "load the voice-mode states");
  const body = (await res.json()) as { enabled?: unknown };
  return Boolean(body.enabled);
}

// POST /sessions/voice-mode/all { enabled } - turn voice mode on (enabled=true) or off (false) for EVERY
// session at once (issue #1765). The Gateway walks the whole roster and fans the per-session voice-mode
// write out itself, so this is ONE call for the caller. Sessions whose owning computer is offline are
// skipped and reported, never failing the batch. Enabling spends per-turn narration credits on every
// session it switches on, so a 402 (out of credits) surfaces the shared credits notice, once.
//
// It is the SWITCH, not just a fan-out: the Gateway persists the intent, so a session that appears
// afterwards is switched on too, by the Gateway's own sweep, without any client doing anything.
export async function setVoiceModeAllSessions(enabled: boolean, signal?: AbortSignal): Promise<VoiceModeAllResult> {
  const res = await gatewayFetch(`/sessions/voice-mode/all`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", ...authHeaders() },
    body: JSON.stringify({ enabled }),
    signal,
  });
  if (!res.ok) {
    if (res.status === 402) throw creditsErrorFrom(await res.json().catch(() => ({})));
    throw await GatewayError.from(res, "change voice mode for every session");
  }
  const body = (await res.json()) as Partial<VoiceModeAllResult>;
  return {
    enabled: Boolean(body.enabled),
    total: Number(body.total ?? 0),
    changed: Number(body.changed ?? 0),
    skipped: Number(body.skipped ?? 0),
    sessions: Array.isArray(body.sessions) ? body.sessions : [],
  };
}
